/** One decision a venture has to make, in a decisions/ folder beside the record it decides (EE-054), like a Next.js file beside its route: decisions/<record>[.<topic>].decision.json decides <record>.json in the folder that holds decisions/. The decision log (decision.schema.json) stays the append-only history; this is the live decision. node schema/decisions.mjs gathers them into the decision matrix. */
export type DecisionRecord = {
  /** Unique within the venture. The roots venture and foundation are reserved. */
  id: string;
  /** What has to be decided, as a question */
  question: string;
  /** The ideas in the founder's idea dump this decision comes from, by id (purpose/ideas/map.mdx), so a decision can be traced back to the founder's own words (EE-061) */
  ideas?: string[];
  /** What the decision settles: a record type, a venture-relative file, or both. Defaults to the record its file name names. */
  decides?: {
    /** A record type in schema/data-model.json */
    record?: string;
    /** A venture-relative file, such as purpose/icp.json */
    path?: string;
  };
  /** The strategic-foundation statement this decision settles (purpose/strategic-foundation.json), if any. It then stands in for that statement in the matrix and is part of the foundation. */
  statement?: string;
  /** The layer it belongs to; defaults to the decided record's layer */
  layer?: "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface" | "system";
  /** The decision class (governance/decision-rights.json) this decision belongs to. A delegation grant can let a role merge decisions of a class (may_merge); a one-way-door class is never delegated, and with no class only the founder merges */
  class?: string;
  /** The decision this one depends on. Defaults to foundation for a foundation record, else venture. */
  parent?: string | null;
  /** fail-closed: while this decision is open, decisions under it wait and agents only draft. fail-open: work under it goes on. inherit: the parent's boundary. The venture root and the foundation fail closed; a product fails open (EE-054). */
  boundary?: "fail-closed" | "fail-open" | "inherit";
  /** The phase in which it must be made. One needed in a later phase than the venture's is speculative and held back (EE-057). */
  needed_in?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  /**
   * When it must be decided, for a decision with a real deadline (a launch, a hackathon, a filing). An open decision past its due time renders overdue; a due time overrides needed_in, so a dated decision is never held back as later.
   * @format date-time
   */
  due?: string;
  status: "open" | "decided" | "deferred" | "withdrawn";
  options?: string[];
  answer?: string | null;
  /** Who decided: a person's name. An agent never decides a fail-closed decision. Deprecated in favour of provenance.approved_by, which it must equal when both are present. */
  decided_by?: string | null;
  /**
   * @format date-time
   */
  decided_at?: string | null;
  /** The decision log entry that records it, such as D-012 or EE-054 */
  logged_as?: string;
  note?: string;
  /** Who worded and who approved the decision, when, and in which phase (EE-058). An agent's wording waits with drafted_by alone; a decided decision needs approved_by, approved_at and phase. */
  provenance?: {
    /** Who wrote the wording */
    drafted_by: {
      /** framework: Naive asked the question itself, as a convention (the product foundation); a person still answers it */
      kind: "person" | "agent" | "framework";
      /** The person's name or the agent's id */
      id?: string;
    };
    /** The person who approved the wording or changed it. Never an agent. */
    approved_by?: string;
    /**
     * @format date-time
     */
    approved_at?: string;
    /** The venture's phase when it was approved */
    phase?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    /** unverified: the approval came through a door with no sign-in, so approved_by is the venture's founder by default, not a checked identity, and no wording is claimed. verified: the venture console checked the person's session, and signer_account names the account */
    signer?: "unverified" | "verified";
    /** The account a door with sign-in checked; set with signer: verified */
    signer_account?: string;
    /** approved: the drafted wording as it was; changed: the approver altered it; own: the approver wrote it */
    wording?: "approved" | "changed" | "own";
    /** The decision class in governance/decision-rights.json under which the approver could decide, when authority was delegated */
    authority?: string;
    /** Where the approval was given, such as the Decision Docket or a decision card */
    via?: string;
    /** The reasons this version was approved on, frozen at approval with each local citation's sha256. If a cited file changes later the decision renders stale: the reason it was decided changed */
    reasons?: DecisionRecordReason[];
  };
  /** What the decision is expected to achieve, and later what happened; the evaluations it is tested against (EE-058). Outcomes, not activities. */
  outcomes?: {
    id: string;
    /** The outcome expected */
    projected: string;
    /** When it should be visible: a date-time, a date or a phase. A pending outcome past a date-time or date is due for its actual result. */
    by?: string;
    /** How it will be checked */
    measure?: string;
    /** What happened */
    actual?: string | null;
    result?: "pending" | "met" | "partly" | "missed";
    recorded_by?: string;
    /**
     * @format date-time
     */
    recorded_at?: string;
    evidence?: string[];
  }[];
  /** Activities this decision opens that were closed before it (EE-058), and for whom */
  unlocks?: {
    activity: string;
    /** Roles, people or agents it opens for; empty means everyone */
    for?: string[];
    /** The routes the activity uses, as globs such as operations/** (robots syntax). Until the decision is made, the router refuses agents those routes (for the actors in for, or every agent). */
    routes?: string[];
  }[];
  /** The founder's messages this record was made from (naive diagnose catches) */
  conversation?: ConversationRef[];
  /** A publish decision (class public-commitment), written by naive publish before anything goes out. One-way doors (hard to undo) are decided by the founder; two-way doors by the founder or a role delegated in governance/delegation.json. An agent never approves. */
  publish?: {
    channel: string;
    artifact: string;
    sha256: string;
    url?: string;
    action?: "publish" | "rollback";
    /** two-way: easy to undo (a private artifact, a draft page). one-way: hard to undo (a public post, an email sent, a launch, anything indexed or cached). After Bezos's Type 1 and Type 2 decisions (2015 shareholder letter). */
    door: "one-way" | "two-way";
    exposure: {
      level: "low" | "medium" | "high";
      who?: ("competitor" | "investor" | "customer" | "legal-regulatory" | "brand" | "public")[];
      note?: string;
    };
    reversibility: {
      how: string;
      takes?: string;
    };
    /** founder, or the role delegated under governance/delegation.json */
    approver_role?: string;
    /**
     * @format date-time
     */
    not_before?: string;
  };
  /** Why: claims for and against the decision and the context it rests on, each with citations. Approving freezes them into provenance.reasons */
  reasons?: DecisionRecordReason[];
  /** This wording's version. Changing a decided decision makes a new version; earlier ones stay in versions (decision versions, 2026-10-29) */
  version?: number;
  /** Earlier versions, oldest first, kept so any of them can be rolled back to. Each is the decision as it stood, without its own versions */
  versions?: {
    version: number;
    status: string;
    answer?: string | null;
    options?: string[];
    provenance?: {
      [key: string]: unknown;
    };
    merged?: {
      [key: string]: unknown;
    };
    superseded_at?: string;
    [key: string]: unknown;
  }[];
  /** An agent's new wording for a decided decision, waiting for a person. The decided version stays current; approving promotes this to the next version (EE-058: an agent never decides or un-decides) */
  proposed?: {
    answer: string;
    options?: string[];
    drafted_by: {
      [key: string]: unknown;
    };
    proposed_at?: string;
  };
  /** Where a merge writes the decided answer: a venture-relative file and a dotted field, such as venture.json core.promise */
  applies_to?: {
    file: string;
    field: string;
  }[];
  /** The version a merge applied to applies_to, and who merged it. Approving and merging are separate steps, and merging may be delegated */
  merged?: {
    version: number;
    by: string;
    at: string;
    files?: string[];
  };
  /** When this version restores an earlier one, the version it restores */
  rolled_back_from?: number;
  /** How reversible the decision is. A one-way door is heavy: the decision index weighs it more and carries propagation further through it (schema/decision-index.mjs). */
  door?: "one-way" | "two-way";
  /** The venture requirements (foundation/requirements/<id>.json) this decision satisfies, is constrained by, or violates. A heavy requirement lifts a later-phase decision into the current phase; a violation is flagged now (schema/decision-index.mjs). */
  requirements?: {
    id: string;
    relation: "satisfies" | "constrains" | "violates";
  }[];
  /** Ids of decisions that cannot be made until this one is. An edge in the decision index. */
  blocks?: string[];
  /** Ids of decisions whose answers may conflict with this one. An edge in the decision index. */
  conflicts?: string[];
};

/** One reason for or against a decision, or context it rests on, with the records it cites (dynamic decision index, item 4) */
export type DecisionRecordReason = {
  claim: string;
  kind: "for" | "against" | "context";
  citations?: {
    /** A venture-relative record path, an evidence id, a research cell id or a decision id */
    ref: string;
    /** sha256 of the cited file when it was cited; computed in code for a local file */
    version?: string;
    /** Where in the cited record, such as a field path or a line */
    locator?: string;
    note?: string;
  }[];
};

/** Who may decide what (EE-017). The template lives at governance/venture-template/decision-rights.json; a venture may tighten a class (move it to a higher level or a more senior owner) in <venture>/governance/decision-rights.json, and loosening one needs an owner decision. Levels follow RAPID and DACI: decide, decide-inform, recommend-approve, escalate. */
export type DecisionRights = {
  register: "decision-rights";
  updated?: string;
  governed_by?: string;
  /** True for the template; a venture's file omits it or sets false */
  template?: boolean;
  /** A venture file: path to the template it tightens */
  extends?: string;
  levels?: {
    [key: string]: string;
  };
  note?: string;
  classes: {
    id: string;
    description?: string;
    /** Role id from the roles register */
    owner: string;
    level: "decide" | "decide-inform" | "recommend-approve" | "escalate";
    condition?: string;
    /** A venture file: the decision that tightened or loosened it */
    decision?: string;
  }[];
};

/** An ordered set of frames from the decision library, at packages/<function>/roadmaps/<id>.json. A roadmap reuses frames and holds no answers: installing it (naive roadmap install <id>) proposes each step's decisions open, and the founder decides. Versioned like a package; a venture that switches roadmaps keeps the decisions already made. schema/check-roadmap.mjs rejects cycles, unknown frames, steps with no decider and one-way doors delegated away from the founder. */
export type DecisionRoadmap = {
  id: string;
  title: string;
  /** The package it lives in */
  function: string;
  version: string;
  description?: string;
  /** Where the ordering comes from, such as a public playbook it was distilled from */
  source?: string;
  steps: {
    id: string;
    /** A frame id in packages/*\/frames */
    frame: string;
    order: number;
    needed_in?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    /** Step ids that must be decided first */
    depends_on?: string[];
    /** one-way: hard to undo, so the founder decides it */
    door: "one-way" | "two-way";
    /** The role that decides, under the delegation suite; founder for every one-way door */
    decided_by: string;
    /** The role that merges the decided work */
    merged_by?: string;
    /** Evidence or lint checks that must pass first */
    requires?: string[];
  }[];
};

/** A decision log: the schema's own (docs/decisions/decisions.json, ids EE-NNN), or any venture's, with its own id prefix. Entries are appended, never rewritten; a changed decision is a new entry that supersedes the old one. */
export type Decision = {
  /** Whose decisions these are */
  log: string;
  /** Id prefix, e.g. EE for the schema itself */
  prefix: string;
  decisions: {
    id: string;
    /**
     * @format date
     */
    date: string;
    decision: string;
    why?: string;
    status: "proposed" | "in-force" | "superseded" | "withdrawn";
    supersedes?: string[];
    related?: string[];
  }[];
};

/** Who has handed which decision classes to whom. The founder (the chief delegator) is the root and holds every class; every other role holds only what a grant gives it, and may pass on only what it holds with may_redelegate. Classes listed in never_redelegated may be granted by the founder but not passed on; classes in one_way_doors are never delegated at all. The template lives at governance/venture-template/delegation.json; a venture keeps its own at <venture>/governance/delegation.json. Checked by schema/check-delegation.mjs. */
export type Delegation = {
  register: "delegation";
  updated?: string;
  template?: boolean;
  /** A venture file: repo-relative path to the template it customizes. The template's never_redelegated and one_way_doors bind the venture too, and an extends that cannot be honored is refused. Grants are not inherited */
  extends?: string;
  note?: string;
  /** The chief delegator's role id (founder) */
  root: string;
  /** The people who hold the root role, by name. Only they approve a one-way publication (schema/publish.mjs) or merge as the founder (schema/decisions.mjs). The template leaves it out; a venture names its own founders */
  founder?: string[];
  never_redelegated?: string[];
  /** Irreversible classes; they stay with the founder */
  one_way_doors?: string[];
  grants: {
    id?: string;
    /** Grantor role id */
    from: string;
    /** Grantee role id */
    to: string;
    classes: string[];
    /** "venture" for all of it, or a route or path prefix such as engineering/ that narrows it */
    scope: string;
    may_redelegate: boolean;
    /** May merge or land work under these classes without the grantor */
    may_merge: boolean;
    /**
     * Last day the grant holds; null for until revoked
     * @format date
     */
    expires: string | null;
    /** The decision that made the grant */
    decision?: string;
  }[];
};

/** The departments a venture can import (EE-047): APQC Process Classification Framework categories, each tagged with its place in Porter's value chain and given need-now priors (EE-028). The framework's copy is operations/departments.json. */
export type DepartmentCatalog = {
  version: string;
  note?: string;
  departments: {
    id: string;
    label: string;
    apqc: {
      id: string;
      name: string;
    };
    value_chain: "primary" | "support";
    /** The value-chain activity it falls under (Porter 1985) */
    porter: string;
    /** What its folder in the governance layer holds */
    governance: string;
    /** What its folder in the operations layer holds */
    operations: string;
    /** Probability a venture needs it, per phase */
    base: {
      [key: string]: number;
    };
    when?: {
      if: string;
      phase?: string;
      at_least?: number;
      at_most?: number;
    }[];
    why: string;
  }[];
};

/** The tag in each of a venture's department folders (EE-047): which department the folder is and where it sits in the value chain. It lives in the folder at <layer>/departments/<id>/department.json, or under an optional grouping folder, <layer>/departments/primary/<id>/ or support/<id>/, which is for looking at only; the tag, not the folder, says what the department is. Its values must match operations/departments.json. */
export type Department = {
  department: string;
  value_chain: "primary" | "support";
  /** The APQC category id */
  apqc: string;
  /** The role that heads it, from the roles register */
  owner?: string;
};

/** A set of evals for a skill, a product or the agent environment (EE-017): prompts with the expected behaviour and assertions. A run of a suite writes evidence (evidence.schema.json). Fits the existing evidence/evals/*.json files. */
export type EvalSuite = {
  skill_name?: string;
  /** Product or skill id the suite tests, when not a skill */
  subject?: string;
  /** Version of the suite (legacy name) */
  harness_version?: string;
  description?: string;
  evals: {
    id: number;
    eval_name?: string;
    prompt: string;
    expected_output: string;
    files?: string[];
    systems_invoked?: string[];
    handoff_files_touched?: string[];
    assertions?: {
      name: string;
      check: string;
      /** When set, the assertion is programmatic: the command decides it */
      command?: string;
    }[];
  }[];
};

/** The result of one run of a check or eval, stored at <venture>/evidence/results/<id>.json (EE-017). It names what was checked, at which version, each assertion's outcome and the output that shows it. Results are append-only: a new run writes a new file. Handoffs point at results to prove their done-criteria. */
export type Evidence = {
  id: string;
  subject: {
    kind: "handoff" | "product" | "skill" | "venture" | "suite";
    id: string;
    /** Commit, tag or version the run checked */
    version?: string;
  };
  /** Path to the eval suite, when the run came from one */
  suite?: string;
  /**
   * @format date-time
   */
  ran_at: string;
  /** Who or what ran it: a CI job, a session id, a role */
  runner: string;
  results: {
    /** A handoff done-criterion id, or an eval assertion name */
    criterion: string;
    /** judged: scored by a model against a rubric, which counts as evidence only for review and evals, never conformance */
    kind: "conformance" | "self-proof" | "review" | "judged";
    passed: boolean;
    command?: string;
    /** The output, trimmed to what shows the outcome */
    output?: string;
    /** Path or link to a screenshot, log or report */
    artifact?: string;
    /** For review results: the role that judged it, which must be the criterion's reviewer and not the handoff's holder */
    by?: string;
  }[];
  /** True only when every result passed */
  passed: boolean;
};

/** A phase's canonical exit criteria, at <venture>/foundation/exit-criteria/<phase>.json: what must be true to leave the phase, each serving a goal measure. The lifecycle gate (schema/lifecycle.mjs) reads these; a criterion is met when a person says so. */
export type ExitCriteria = {
  phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  venture?: string;
  criteria: {
    id: string;
    statement: string;
    /** Measure ids this criterion moves the venture toward */
    serves?: string[];
    evidence?: string;
    met?: {
      by: string;
      /**
       * @format date-time
       */
      at: string;
      evidence?: string;
    } | null;
  }[];
  framework?: string;
  updated?: string;
};

/** How the venture might end and what each owner would get, at <venture>/governance/exit.json (EE-022): the exit paths it keeps open and the sale values to model. Payouts are never typed here: schema/payouts.mjs computes them from ownership.json for each scenario. */
export type Exit = {
  paths: {
    /** hold: no exit, the owners keep it */
    kind: "acquisition" | "ipo" | "secondary-sale" | "merger" | "management-buyout" | "wind-down" | "hold";
    stance: "preferred" | "open" | "ruled-out";
    note?: string;
  }[];
  scenarios?: {
    id: string;
    /** Proceeds to the owners after debts and costs */
    value: number;
    note?: string;
  }[];
};

/** The summary of what founders agreed with each other, at <venture>/governance/founder-agreement.json (EE-022), with the full text (or the signed document's location) in founder-agreement.md beside it. Equity and vesting live in ownership.json and are not repeated here. Required once two or more founders share ownership. */
export type FounderAgreement = {
  /**
   * null until every founder has signed
   * @format date
   */
  signed: string | null;
  /** Path to the prose agreement or the signed document */
  document: string;
  founders: {
    /** Holder id in ownership.json */
    holder: string;
    role: string;
    commitment: "full-time" | "part-time";
    /** Has assigned to the venture the work and ideas they brought or make */
    ip_assigned: boolean;
  }[];
  departure?: {
    good_leaver?: string;
    bad_leaver?: string;
    buyback?: "unvested-only" | "unvested-at-cost" | "none";
  };
  /** How founders break a tie */
  deadlock?: string;
};

/** One founder of the venture (people/founders/<id>.json): role, the functions they own, when they joined, and where their founder agreement is. One file per founder, so each founder's record changes on its own. */
export type Founder = {
  id: string;
  name: string;
  role: "founder" | "co-founder" | "general-partner";
  /** The functions this founder owns, in the flat layout. In the structured layout (EE-086) they are read from venture.json */
  hats?: ("strategy" | "products" | "marketing-and-sales" | "supply-chain" | "service-delivery" | "customer-service" | "human-capital" | "it" | "finance" | "assets" | "risk-and-compliance" | "external-relationships" | "capabilities")[];
  /**
   * @format date
   */
  joined: string;
  agreement?: {
    path: string;
    signed: boolean;
  };
  /** Who the founder is, as a mentor learns it (Torian's playbook). Built from a template of attributes in purpose/frameworks/founder-profile/attributes.json; any attribute from that library can be added. Each attribute is a list of entries, prose in the founder's words with an optional type */
  profile?: {
    /** The template it started from; default if absent */
    template?: string;
    /** The mentor's prose portrait, for reasoning models */
    summary?: string;
    attributes?: {
      [key: string]: {
        /** In the founder's own words */
        text: string;
        /** One of the attribute's types in purpose/frameworks/founder-profile/attributes.json */
        type?: string;
        /** For a strength or weakness of type venture-function: the venture function it is about */
        function?: string;
      }[];
    };
    /** The founder said the profile reads true */
    confirmed?: boolean;
  };
};

/** One recurring venture problem, as a shape, at packages/<function>/frames/<id>.frame.json. A frame is to Naive what a component is to a React component library. It holds the goal, the decisions hidden in the founder's sentence, the premises that sentence assumes and the moves to attack them, and what current information a lookup must supply. It never holds an answer: no instrument, vendor, term or market norm, because those go stale and can be wrong. schema/frames.mjs matches a frame to the founder's words, reads the props from the venture's records, has a model judge each premise yes, no or unknown, and proposes the frame's decisions with open options for the founder to decide. */
export type Frame = {
  id: string;
  title: string;
  /** The venture functions the problem belongs to; the first is the package the frame lives in */
  functions: string[];
  /** Sentences a founder says when they have this problem, in a founder's words */
  triggers: string[];
  /** The end the decisions serve; {prop} placeholders are filled from the venture */
  goal: string;
  /** The chain the founder's sentence assumes, in order */
  premises: {
    id: string;
    /** What the founder's sentence assumes, as a yes/no proposition about this venture */
    claim: string;
    /** The premise attack applied to it, one of schema/frames.mjs ATTACKS */
    attack: string;
    /** The props the judgment of this premise needs */
    reads?: string[];
  }[];
  /** The premise attacks the frame uses (the hooks of the library) */
  attacks: string[];
  /** The trade the founder's sentence forces, asked as: is it false, a real trade-off, or a sequence? */
  dichotomy?: string;
  /** The better question the frame leaves the founder with; {prop} placeholders are filled from the venture */
  reframe: string;
  /** Smaller frames this one is built from */
  composes?: string[];
  /** The venture facts the frame reads, never stores: phase, goal, runway, revenue, cap_table, jurisdiction, control_rights */
  props: string[];
  /** What current information the frame needs and how fresh it must be. The lookup itself is a kit's skill; the frame says only what to look for. */
  freshness: {
    /** What a lookup must find, described as a problem, never as a named answer */
    look_for: string[];
    filter_by?: string[];
    max_age_days: number;
    cite: true;
  };
  /** What a model that fetches the frame must do, in order */
  reasoning: string[];
  /** The decisions the frame proposes, each open for the founder to decide */
  emits: {
    id: string;
    question: string;
    /** Options that describe the problem's own parts, never a named answer; options from a lookup are added at run time with their date and source */
    options?: string[];
    options_from?: "frame" | "lookup";
    layer?: "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface";
    needed_in?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  }[];
  /** Worked cases, to evaluate a model's judgments against */
  cases?: {
    id: string;
    /** The props of a worked venture */
    facts: {
      [key: string]: unknown;
    };
    /** The premise verdicts and dichotomy a good judgment reaches for these facts */
    expect: {
      [key: string]: unknown;
    };
  }[];
};

/** A framework for thinking, at frameworks/<id>/framework.json: its vocabulary, its questions (frames), a template and how each of its answers lands in canonical records (maps_to). A framework reads and writes the canonical schema and never changes it (Torian, 2026-10-30). schema/check-frameworks.mjs checks that every maps_to targets a canonical route. A founder's own frameworks sit in the workspace's frameworks/ folder with the same shape, plus template.md and playbook.md (schema/user-frameworks.mjs). */
export type Framework = {
  id: string;
  title: string;
  purpose?: string;
  /** The framework's own terms and what each means in canonical words */
  vocabulary?: {
    [key: string]: string;
  };
  frames: {
    id: string;
    question: string;
    /** The framework field the answer fills */
    answers?: string;
  }[];
  template?: string | null;
  /** The skill that runs the framework with the founder; it stays at its layer path */
  skill?: string | null;
  /** A module rendering the framework's view from canonical records */
  adapter?: string | null;
  /** Checks that belong to the framework and may read its own fields */
  checks?: string[];
  maps_to: {
    framework_field: string;
    canonical_route: string;
    canonical_field: string;
    note?: string;
  }[];
  /** The playbook: the steps for running the framework, a path relative to the root that holds frameworks/ */
  playbook?: string | null;
  /** Who owns the framework: a person for a founder's own, Naive for a built-in one */
  owner?: string;
  /** internal stays in the workspace; public may be published (naive framework publish) */
  visibility?: "internal" | "public";
  status?: "draft" | "stable";
};

/** One line of a venture's freshness log (<venture>/knowledge/freshness.jsonl, Revalidating V-1, V-2, V-5, V-7): an on-demand revalidation (a tag, a folder path or a package marked stale, like revalidateTag and revalidatePath), a check that a record is still right without changing it (verify), or a phase change. Append-only; each append is also a line in the provenance log. schema/freshness.mjs writes and reads it. */
export type FreshnessLog = {
  /**
   * @format date-time
   */
  at: string;
  /** revalidate: mark stale on demand. verify: a record was checked and is still right; its age starts again. phase: the venture changed phase */
  event: "revalidate" | "verify" | "phase";
  /** revalidate and verify: what is marked. tag: one record file and everything that depends on it. path: every record under a folder. package: every record of a package's record types */
  target?: {
    kind: "tag" | "path" | "package";
    value: string;
  };
  /** phase: the phase before */
  from?: string;
  /** phase: the phase after */
  to?: string;
  reason?: string;
  /** A revalidate of the validation package because the venture pivoted */
  pivot?: boolean;
  by: {
    kind: "person" | "agent";
    id?: string;
    model?: string;
    session?: string;
    harness?: string;
    via: "cli" | "mcp" | "api" | "router";
  };
};

/** How long records stay fresh (Revalidating, V-1 to V-3), after Next.js cacheLife profiles (stale, revalidate, expire) plus two Naive adds: per_phase (stale once the venture changes phase) and live (never frozen into a release; a live hole). The framework's defaults are knowledge/freshness.json; a venture overrides profiles and record assignments under freshness in its naive.config.json. schema/freshness.mjs reads both. */
export type FreshnessProfiles = {
  $schema?: string;
  note?: string;
  version?: string;
  /** The profile a record type gets when records names none */
  default?: string;
  profiles?: {
    [key: string]: FreshnessProfilesProfile;
  };
  /** Profile name by record type id, or by route prefix (validation, foundation/problem); a route prefix wins over the record type, and the longest prefix wins */
  records?: {
    [key: string]: string;
  };
};

/** Seconds, or a number followed by s, m, h, d or w */
export type FreshnessProfilesDuration = number | string;

export type FreshnessProfilesProfile = {
  /** How long an agent may reuse what it read without reading it again */
  stale?: FreshnessProfilesDuration;
  /** After this long since it was last checked, the record is stale: readable with a stale flag, to be checked or redone */
  revalidate?: FreshnessProfilesDuration;
  /** After this long it is expired: not relied on, and not frozen into a release */
  expire?: FreshnessProfilesDuration;
  /** Stale once the venture changes phase after the record was last checked */
  per_phase?: boolean;
  /** A fast-changing record (pipeline, money, streams): never frozen into a release, it stays a live hole */
  live?: boolean;
  note?: string;
};

/** The fund's economics and structure (fund/terms.json): target size, vintage, fees, carry and term, and the closes so far. */
export type FundTerms = {
  venture: string;
  target_size: {
    amount: number;
    currency: string;
  };
  vintage: number;
  structure?: "limited-partnership" | "llc" | "rolling-fund" | "syndicate" | "evergreen";
  /** Annual fee as a fraction of commitments */
  management_fee: number;
  carry: number;
  term_years: number;
  gp_commit?: number;
  closes?: {
    /**
     * @format date
     */
    date: string;
    committed: {
      amount: number;
      currency: string;
    };
  }[];
};

/** What a fund invests in and why it wins (fund/thesis.json): rounds, sectors, geographies, check size, and the edge. The fund's strategic foundation, as the problem record is a startup's. */
export type FundThesis = {
  venture: string;
  /** The thesis in one or two sentences */
  statement: string;
  rounds: ("pre-seed" | "seed" | "series-a" | "series-b" | "growth" | "late")[];
  sectors: string[];
  geographies?: string[];
  check_size: {
    min: number;
    max: number;
    currency: string;
  };
  /** Target ownership at entry, as a fraction */
  ownership_target?: number;
  /** Why this fund sees, wins or helps deals others do not */
  edge?: string;
  why_now?: string;
};

/** A package's own terms, at glossary/<package>.json (Y-2, the scoping idea of CSS Modules): each term stays local to the package unless export is true, so an agent working in another package sees only exported terms. Two packages exporting one term with different meanings fail schema/check-brand.mjs. Version 0.x, unevaluated. */
export type Glossary = {
  /** The package whose terms these are; the file is glossary/<package>.json */
  package: string;
  terms: {
    term: string;
    meaning: string;
    /** true: other packages see it too */
    export?: boolean;
  }[];
};

/** A canonical goal, at <venture>/foundation/goals/<id>.json: what the venture means to reach, by when, how anyone would know (measures with targets) and who owns it. Framework-neutral: the telos, ambition tiers, OKRs and other frameworks for thinking write goals through their maps_to and never change this shape (Torian, 2026-10-30: opinionated schema, swappable frameworks). Requirements derive from goals and measures; exit criteria serve measures. */
export type Goal = {
  id: string;
  venture?: string;
  /** The goal in one sentence */
  statement: string;
  /** venture: the end the venture exists for. owner: what the owners intend once it is reached (hold, sell, list, wind down). scale: how far through the phases the venture means to go. product, function: a goal of one product or function. learning: what the venture must find out */
  kind: "venture" | "owner" | "scale" | "product" | "function" | "learning";
  /** The year it should be reached by, a date, a phase id, or 'open' */
  horizon?: number | string;
  /** What is true in the world when it is reached */
  end_state?: string;
  /** A goal's chosen value when its kind has a fixed set: the scale (hobby, survival, lifestyle, managed-growth, aggressive-growth) or the owner path (acquisition, ipo, secondary-sale, merger, management-buyout, wind-down, hold) */
  value?: string;
  why?: string;
  measures?: {
    id: string;
    statement: string;
    target?: string | number;
    unit?: string;
    primary?: boolean;
    /** A framework's own classification of the measure, kept as written */
    kind?: string;
  }[];
  /** The person or role who owns the goal */
  owner?: string;
  /** The framework for thinking the goal was written through (frameworks/<id>), if any */
  framework?: string;
  updated?: string;
  /** The founder's messages this record was made from (naive diagnose catches) */
  conversation?: ConversationRef[];
  decision?: string;
};

/** One unit of delegated work, stored at <venture>/operations/handoffs/<id>.json (EE-017). It is the machine half of handoff contract v2 (operations/handoff-v2.md): who holds it, which decision rights it carries, how it is checked, and where it stands. The brief (outcome, work, context) is prose in a Markdown file beside it. schema/check-ready.mjs checks it is ready before work starts; schema/check-execution.mjs checks it against the venture's decision rights and evidence. */
export type Handoff = {
  id: string;
  title: string;
  /** Venture id */
  venture: string;
  /** Product ids the work serves */
  products?: string[];
  /** Decision ids this executes (EE-NNN, G-NNN, D-NNN or an ADR path) */
  governed_by?: string[];
  /** Optional: the build-method assignment the work runs under, such as a MAD A-NNN, or none. MAD is a separate product, so Mentura records the reference and does not check it (EE-019, EE-038) */
  assignment?: string;
  /** Files the work needs before it can start, from the repo root; check-ready.mjs makes sure they exist */
  inputs?: string[];
  /** Role id from the roles register that holds it (builder, architect and so on) */
  role: string;
  /** Path to the Markdown brief, relative to this file */
  brief: string;
  /** Decision-rights class ids the holder may use without reporting back. Anything outside them is escalated. */
  decision_classes: string[];
  done_criteria: {
    id: string;
    /** conformance: an objective check run as a command, with no model and no reviewer. self-proof: the change exercised for real, with evidence attached (EE-006). review: fit to intent, judged by the named role. */
    kind: "conformance" | "self-proof" | "review";
    /** The command to run, or for review the question the reviewer answers */
    check: string;
    /** Role id, for review criteria */
    reviewer?: string;
  }[];
  /** draft until schema/check-ready.mjs passes and is recorded; then ready, in-progress, escalated or done */
  status: "draft" | "ready" | "in-progress" | "escalated" | "done";
  /** Written by check-ready.mjs --record when every readiness item passed, before execution started */
  ready_check?: {
    /**
     * @format date-time
     */
    at: string;
    by: string;
    version: string;
    items: number;
    [key: string]: unknown;
  };
  /** Session or run id of the holder */
  claimed_by?: string;
  /** Session that wrote the handoff */
  session_id?: string;
  /** Session that assigned it, for lineage */
  parent_session_id?: string;
  attempts: number;
  max_attempts: number;
  /** Wall-clock or spend cap per run, such as 2h or $20 */
  run_cap: string;
  /** Pull request link once opened */
  pr?: string;
  /** Paths to eval or check results (evidence.schema.json) that prove the done-criteria */
  evidence?: string[];
  escalations?: {
    /** The decision-rights class, or attempts or run-cap */
    class: string;
    question: string;
    /** Role id */
    to: string;
    blocks?: string;
    continued?: string;
    answer?: string;
  }[];
  /** A failure that could recur, and the check one rung higher that would catch it (prose, skill, rule, static analysis, code) */
  lesson?: string;
  /** Required when the handoff publishes (public-commitment in decision_classes or escalations): the channel and content rule in the venture's publication policy (EE-025) */
  publication?: {
    channel: string;
    content: string;
  };
};

/** One ideal customer profile (EE-051), at <venture>/foundation/icp/<id>.json: the 'who' foundation statement is the enumeration of these records, one primary. Each is specific enough to go and find ten of them: two founders who differ in what they can do (an excellent engineer, a founder who cannot code) are two profiles, not one. Gated like the telos: an agent's write is a draft the founder accepts. Replaces the single foundation/icp.json, which the icp-profiles migration splits. */
export type IcpProfile = {
  venture?: string;
  /**
   * @format date
   */
  updated?: string;
  /** The decision that set it, such as EE-045 */
  decision?: string;
  /** The profile's id: unique in the venture and equal to its file name (foundation/icp/<id>.json) */
  id: string;
  /** Who they are, specifically enough to find ten of them */
  who: string;
  /** One line naming who they are; the venture's promised-to statement shows it (EE-052) */
  short?: string;
  /** Exactly one profile is primary */
  primary?: boolean;
  customer?: "b2b" | "b2c" | "b2g";
  /** The phases of their own venture they are in, when they are founders */
  phases?: ("discovery" | "validation" | "beachhead" | "scale" | "platform")[];
  /** What must be true of them */
  traits?: string[];
  /** What they are trying to get done (jobs to be done) */
  jobs?: string[];
  /** Ids of the problem record's forms they have */
  problem_forms?: string[];
  /** Where to reach them: communities, channels, events */
  where_to_find?: string[];
  /** Who is out of scope, and why */
  not?: string[];
  /** The parts this profile plays in a purchase (the buying center: Webster and Wind 1972; initiator added by Bonoma 1982). One person may hold several; a solo founder or a consumer usually holds them all. */
  buying_roles?: ("initiator" | "user" | "influencer" | "decider" | "buyer" | "gatekeeper")[];
  /** Other profiles (ids) through whom the venture reaches this one, such as a channel partner in a B2B2C venture (EE-064) */
  reached_through?: string[];
  /** The customer type from the marketing matrix (operations/marketing/site/matrix.json customer_types), when the founder sets it; otherwise it is judged from who (EE-063) */
  customer_type?: string;
  /** The founder's messages this record was made from (naive diagnose catches) */
  conversation?: ConversationRef[];
};

/** The structured form of a founder's idea map (EE-060): a Merkle DAG. Each idea's hash covers its text and the hashes of the ideas it builds on, so a change upstream changes every hash downstream. Written by purpose/frameworks/idea-map/graph.mjs; it holds no decisions. */
export type IdeaGraph = {
  version: string;
  venture: string;
  phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  created?: string;
  /** The idea map it was built from, with that file's hash */
  source?: string;
  /** Hash over the hashes of the ideas nothing builds on: one value for the whole graph */
  root: string;
  /** Who judged the dependencies: Jev's typed answers, or Naive's convention of which records build on which */
  judged_by: "jev" | "convention";
  weights?: {
    [key: string]: number;
  };
  nodes: {
    id: string;
    hash: string;
    /** The founder's words, unchanged */
    text: string;
    section?: string;
    pillar?: string | null;
    departments?: string[];
    records?: string[];
    exists?: boolean;
    /** Longest chain of ideas before it: its column, left to right */
    depth: number;
    builds_on: string[];
    signal: number;
    parts?: {
      [key: string]: number;
    };
    lane: string;
    [key: string]: unknown;
  }[];
  edges: {
    from: string;
    to: string;
    p: number;
    by?: string;
    [key: string]: unknown;
  }[];
  /** Dependencies left out because they would have closed a cycle */
  dropped?: unknown[];
  lanes: {
    id: string;
    /** sync: its ideas build on each other and move in order; async: it moves on its own, beside the other lanes */
    mode: "sync" | "async";
    ideas: string[];
    department?: string | null;
    signal?: number;
    why?: string;
    [key: string]: unknown;
  }[];
  /** The highest-signal ideas that build on nothing: what to develop next */
  next: string[];
  [key: string]: unknown;
};

/** One tool or service a layer can use. Each layer lists its integrations in <layer>/tooling/integrations.json. Credentials are named, never stored. Entries under interface/ are interfaces, not integrations: they must reach at least three of the five other layers (EE-038) (schema/check-integrations.mjs). Knowledge integrations with a connector are the connector registry (EE-037): a venture's knowledge/sources.json names them by id. */
export type Integration = {
  id: string;
  name: string;
  layer: "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface";
  /** What the layer uses it for, in a few words */
  role: string;
  /** How agents and code reach it */
  interfaces: ("files" | "mcp" | "api" | "sdk" | "cli" | "webhook" | "app")[];
  /** Interface layer only: the other layers a person can work in through it, in one session. At least three of the five. */
  reach?: ("purpose" | "knowledge" | "operations" | "evidence" | "governance")[];
  /** Interface layer only: an agent harness (built around an AI agent's loop, tools and files) or a custom interface built for the system or a venture. */
  interface_kind?: "agent-harness" | "custom";
  status: "in-use" | "candidate" | "rejected";
  /** Why it is in use, a candidate, or rejected */
  reason?: string;
  /** Environment variable names only */
  credentials?: string[];
  /** Path to the skill, MCP config or script that wires it in, when one exists */
  adapter?: string;
  links?: string[];
  /** Knowledge layer only: the module that implements the connector contract (knowledge/connectors/contract.mjs) for this integration, so a venture's knowledge/sources.json can keep records in it (EE-037) */
  connector?: {
    /** Path from the repository root; it exports connect(options). A connector that works offline and names no vendor is framework (knowledge/connectors/); any other is platform (platform/connectors/), EE-041 */
    module: string;
    /** The write modes it supports; the first is its default */
    writes: ("direct" | "pull-request" | "none")[];
    /** The source options it takes, besides id and writes */
    options?: string[];
    /** The command that runs the contract evals against it */
    eval?: string;
  };
};

/** Patterns that mark internal text, which public output must never contain (schema/check-leaks.mjs). Naive's own list is schema/internal-terms.json; a venture's founder edits its own at <venture>/governance/internal-terms.json, for unannounced codenames and internal jargon. A pattern with severity warn is reported without failing, for a term whose status a person has not decided yet. */
export type InternalTerms = {
  note?: string;
  updated?: string;
  /** Who edits the list (the founder) */
  owner?: string;
  patterns: {
    id: string;
    kind?: "decision-id" | "attribution" | "record-path" | "codename" | "phase-jargon" | "draft-marker" | "other";
    /** A JavaScript regular expression, matched with the g flag */
    regex: string;
    why: string;
    severity?: "fail" | "warn";
    /** For a codename: what lifts it, such as the announcement */
    until?: string;
  }[];
};

/** The output of one model step ("use model", EE-073), at <venture>/knowledge/judgments/<id>.json: the package and step that asked, the item it was asked about, the paths the model was given, its typed answer and confidence, the computed values it had to keep, and what code did with it. A judgment is the agent's until a person confirms it; the records it read stay their authors'. Written by schema/model-steps.mjs through the router. */
export type Judgment = {
  /** <package>-<step>-<item>, or <package>-<step> for a step asked once */
  id: string;
  /** The package (or kit) that declares the step */
  package: string;
  /** The step id in the package's use_model */
  step: string;
  /** classify a fragment, judge fit (noul: yes, no or unknown), choose among options, rate on a scale, or draft prose. Only a draft is model-only */
  kind: "classify" | "noul" | "choice" | "score" | "draft";
  /** The record id the step was asked about, for a step asked for each item of a collection */
  item?: string | null;
  /** The question as asked, its {paths} pointing into the state */
  question: string;
  /** The venture-relative files and the field paths the model was given, and nothing else */
  reads: string[];
  /** answer: typed, at or above threshold, and every check passed. overruled: a code check disagreed and the code's value stands. uncertain: below threshold, malformed or unanswered, and routed to a person */
  outcome: "answer" | "overruled" | "uncertain";
  /** The typed answer (the code's value when overruled; null when uncertain) */
  answer: unknown;
  confidence?: number | null;
  threshold?: number | null;
  /** Why the outcome is what it is */
  why?: string;
  /** Computed values the answer had to carry unchanged, and they did */
  kept?: {
    [key: string]: unknown;
  };
  overruled?: {
    judgment?: unknown;
    code?: unknown;
    check?: string;
  };
  /** The open decision a person answers when the judgment is uncertain */
  decision?: string;
  by: {
    kind: "model" | "person";
    model?: string;
    name?: string;
  };
  /** Hash of the question and the state the model was given; a later run reuses the judgment while it is unchanged */
  state_sha256?: string;
  /**
   * @format date-time
   */
  asked_at?: string;
};

/** A Mentura kit (EE-071): an enhanced package, at platform/kits/<name>/kit.json. It extends one Naive package (automations, agent workflows, skills, connectors on top of it) or one framework command (an agent-run upgrade), and never replaces it. The framework reads this manifest as data and runs the kit's entry as its own process; it never imports platform code (schema/kits.mjs). Automations are triggers a venture turns on by listing the kit in naive.config.json kits; each runs only once the package it needs is complete (schema/triggers.mjs). */
export type Kit = {
  name: string;
  title: string;
  purpose: string;
  extends: {
    /** The Naive package it enhances (packages/<name>/package.json) */
    package?: string;
    /** The framework command it extends, such as "upgrade --agent" */
    command?: string;
  };
  /** The kit's program, relative to its folder, run as node <entry> <venture dir> */
  entry?: string;
  agent?: {
    /** The agent it runs by default; MENTURA_AGENT_CMD replaces it */
    command: string[];
    /** Environment variables it reads, by name */
    env?: string[];
  };
  /** Triggers the kit brings; each names the package it needs (needs) */
  automations?: Trigger[];
  /** The steps that call a model ("use model", S-9); empty when none does */
  use_model: string[];
  /** What decides whether the kit's work lands; always framework code */
  checks?: string[];
  status: "built" | "experimental";
  note?: string;
};

/** A venture's source map (<venture>/knowledge/sources.json, EE-037): the sources its records live in and which record types live where. Optional: a record type it does not name, and every record of a venture without one, lives in the venture's own folder (the implicit `venture` source). The venture decides its own layout; Mentura does not. Rules make it a source-of-truth matrix: a system of record per record type, attribute and context, written for a fast model to read (EE-042). Each source names a connector from the registry (an integration with a `connector` in knowledge/tooling/integrations.json). Credentials are named by environment variable, never stored. Beside the sources Naive reads records from, `functions` says where each of the venture's functions keeps its truth outside Naive (EE-083): the repo, hosting and analytics for the product, a payments or store account for sales, the bank for money, a folder or signing service for legal documents. Those are pointers to systems of record; a system Naive reads through code is connected, one it only knows of is pointed. `truth` says where the venture's source of truth as a whole lives. */
export type KnowledgeSources = {
  sources: {
    /** The source's id; `venture` is reserved for the venture's own folder */
    id: string;
    /** An integration id with a connector: filesystem, github */
    connector: string;
    /** How writes reach it; the connector's default when left out */
    writes?: "direct" | "pull-request" | "none";
    /** filesystem: the folder, relative to the venture folder or absolute. github: the folder inside the repository */
    root?: string;
    /** github: owner/name */
    repo?: string;
    /** github: the branch (default main) */
    ref?: string;
    /** github: the environment variable holding a token (default GITHUB_TOKEN) */
    token?: string;
    /** github: the API base, for GitHub Enterprise */
    api?: string;
    /** github: code search (default) or a scan of the files */
    search?: "api" | "scan";
    note?: string;
  }[];
  /** Record type id (from schema/data-model.json) -> source id. Unnamed record types stay in the venture folder. */
  records: {
    [key: string]: string;
  };
  /** The source-of-truth matrix (EE-042). Each rule is one cell: for one record type in one context, its system of record and owner. Every field is present and "*" means any, so a fast model reads a rule without inferring anything. The rule with the most fields that are not "*" wins; two that tie fail the check. `records` is shorthand for rules that match anything. */
  rules?: {
    /** A venture record type id from schema/data-model.json */
    record: string;
    /** "*" for the whole record, or one top-level field mastered elsewhere (such as price). The router reads the field from that source and writes it there, kept at the record's own path as a JSON object holding only that field; the record's own file does not keep a copy. */
    attribute: string;
    /** The venture's phase this rule holds in */
    phase: "*" | "discovery" | "validation" | "beachhead" | "scale" | "platform";
    /** A product id, or "*" */
    product: string;
    /** An account id, or "*" */
    account: string;
    /** Who is reading or writing */
    actor: "*" | "person" | "agent";
    /** A source id from `sources`, or venture for the venture's own folder */
    system_of_record: string;
    /** The role accountable for this cell's data (the MDM data owner), a role id from governance decision rights or the team plan */
    owner: string;
    /** When the same record also lives in other sources, which value wins. Running these rules across vendors is the platform's; the framework only states and checks them. */
    survivorship?: {
      also_in: string[];
      winner: "system-of-record" | "most-recent";
    };
    note?: string;
  }[];
  note?: string;
  /** local: this device is the source of truth; otherwise the address of the host every system is backed up to or hosted on (EE-083) */
  truth?: string;
  /** Each function's systems of record, by department id (operations/departments.json) or legal (EE-083) */
  functions?: { [K in "strategy" | "products" | "marketing-and-sales" | "supply-chain" | "service-delivery" | "customer-service" | "human-capital" | "it" | "finance" | "assets" | "risk-and-compliance" | "external-relationships" | "capabilities" | "legal"]?: {
      systems: {
        /** A system id from schema/systems-catalog.json */
        system: string;
        address?: string;
        /** The source in `sources` that reads it, when it is one */
        source?: string;
        /** connected: read by code (a connector or an integration); pointed: known, not read yet */
        status: "connected" | "pointed";
        /**
         * @format date-time
         */
        synced?: string;
        /** The last sync replayed a saved answer, not the live system */
        fixture?: boolean;
      }[];
      /** What the founder said about this function, in their words */
      note?: string;
    } };
};

/** What one layer of the framework repository holds, at <layer>/layer.json and schema/layer.json for the system layer (EE-018, EE-071). A layer organizes the framework repo. It is not a venture package. Venture packages live at packages/<name>/package.json. A kit is Mentura's word, at platform/kits/. schema/check-data-model.mjs checks this file. */
export type Layer = {
  layer: "system" | "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface";
  /** What the layer is for, in one sentence */
  purpose: string;
  /** The product card that offers this layer's work, as <venture id>/<product id> */
  product?: string;
  skills: {
    id: string;
    /** The SKILL.md, from the repo root */
    path: string;
    /** Optional: the MAD tier a skill serves, for a venture that uses MAD (a separate product since EE-038) */
    tier?: "governance" | "delivery" | "software-engineering" | "automation";
    /** Useful without the rest of the layer */
    standalone?: boolean;
    /** A proposed owning layer or package, when the skill is filed in the wrong place */
    move_to?: string;
    why?: string;
  }[];
  /** Record types this layer owns (data-model ids). Venture records that a package owns are listed on the package, not here. */
  records: string[];
  /** Record types owned elsewhere that this layer's skills and checks read */
  reads: string[];
  /** Record types owned elsewhere that this layer's skills write */
  writes: string[];
  /** Scripts that check or run this layer's records, from the repo root */
  checks: string[];
  /** Known missing parts */
  gaps?: string[];
  /** The layer's name */
  name: string;
};

/** An ordering of the venture development lifecycle, at purpose/frameworks/product-anatomy/playbooks/<id>.json. The five phases, their questions and the set of frames are fixed; a playbook varies the order of decisions, which decisions gate which phase, and the evidence that clears each gate. A venture names its playbook in venture.json lifecycle_playbook (default product-first); schema/lifecycle.mjs reads the gate and its evidence from it. The founder chooses the playbook. */
export type LifecyclePlaybook = {
  id: string;
  title: string;
  version: string;
  description?: string;
  /** The broad order of moves the playbook takes */
  order?: string[];
  /** Decision roadmaps bundled with the playbook */
  roadmaps?: string[];
  phases: {
    phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    /** What clears the phase under this playbook */
    gate: string;
    /** Decision ids that must be decided before the gate passes */
    gating_decisions?: string[];
    evidence: {
      id: string;
      statement: string;
      /** A case-insensitive pattern: a met exit criterion whose id, statement or evidence fits it supplies this evidence */
      match: string;
    }[];
  }[];
};

/** The venture's brand tokens, in the marketing package at marketing/brand.json: colors, typefaces with their licenses, the font each role uses, voice rules (the global stylesheet for words), the logo and marks, outside design systems by reference, and scopes where a route prefix overrides the venture brand (nearer context wins). Read by every agent's layout and every interface; checked by schema/check-brand.mjs. Translates Next.js global CSS, next/font and file-based icons (Y-3, Y-4, Y-5, T-1, T-2, P-24). Version 0.x, unevaluated. */
export type MarketingBrand = {
  version: string;
  venture: string;
  /** The name as the brand writes it */
  name?: string;
  colors?: MarketingBrandColors;
  /** Each typeface, defined once with its license (T-1). self-hosted: its files are in public/ and registered, so a browser makes no outside request; system: the reader's own fonts; remote: served from another host (the check fails it) */
  typefaces?: {
    id: string;
    family: string;
    source: "self-hosted" | "system" | "remote";
    /** An SPDX id such as OFL-1.1, or owned, or licensed */
    license?: string;
    files?: string[];
    url?: string;
    fallback?: string[];
    credit?: string;
  }[];
  /** The font each role uses everywhere, as the root layout applies it (T-2) */
  fonts?: MarketingBrandFonts;
  voice?: MarketingBrandVoice;
  /** The logo and marks (P-24), each a registered file in public/ */
  marks?: {
    kind: "logo" | "icon" | "apple-icon" | "favicon";
    asset: string;
    use?: string;
  }[];
  /** Outside design systems the brand builds on, by reference: linked, with a version and license, never copied in (Y-4) */
  design_systems?: {
    id: string;
    name: string;
    url: string;
    version?: string;
    license: string;
    /** What the venture takes from it */
    uses?: string[];
  }[];
  /** Overrides for a route prefix (a package such as investors, or one item such as investors/deck). Nearer context wins: a deeper prefix over a shallower one, any scope over the venture brand (Y-5, T-2) */
  scopes?: {
    for: string;
    colors?: MarketingBrandColors;
    fonts?: MarketingBrandFonts;
    voice?: MarketingBrandVoice;
    note?: string;
  }[];
};

/** Token name -> hex color */
export type MarketingBrandColors = {
  [key: string]: string;
};

/** Role (body, heading, mono, display...) -> typeface id */
export type MarketingBrandFonts = {
  [key: string]: string;
};

export type MarketingBrandRule = {
  id: string;
  /** A phrase, or phrases, the venture's words never use; matched as whole words, ignoring case */
  avoid: string | string[];
  /** What to write instead */
  use?: string;
  why?: string;
};

export type MarketingBrandVoice = {
  /** How the venture sounds, in a few words each */
  tone?: string[];
  rules?: MarketingBrandRule[];
};

/** The venture's design system, in the marketing package at marketing/design-system.json: the ethos read from the strategic foundation, and every brand choice (color, type, shape, motion, imagery, voice) with why it was made and the records it comes from. The values themselves live in marketing/brand.json; this record says why, so a choice can be revisited when the mission, the ICPs or the market change. Inputs are inherited from other functions through marketing/design-system/inputs, never copied. An agent's write is a draft a person accepts (experience-design). */
export type MarketingDesignSystem = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  /** The brand record that holds the token values */
  brand?: string;
  /** What the venture stands for, in a sentence or two, as the design system reads it */
  ethos: {
    statement: string;
    /** A few adjectives the brand should feel like, such as calm, exact, warm */
    traits?: string[];
    /** What the brand should never feel like */
    avoid?: string[];
    from: MarketingDesignSystemFrom;
  };
  /** The ICP profiles the design speaks to, by id, primary first */
  audiences?: string[];
  choices: {
    area: "color" | "typography" | "spacing" | "shape" | "motion" | "imagery" | "iconography" | "voice" | "layout";
    /** What was chosen, such as a deep ink blue primary, or a humanist sans for body */
    choice: string;
    /** The marketing/brand.json paths it sets, such as colors.primary or fonts.body */
    tokens?: string[];
    /** The reason, in terms of the ethos, the ICPs or the market */
    why: string;
    from: MarketingDesignSystemFrom;
    alternatives?: string[];
  }[];
  /** The components the venture's artifacts are built from, each with the tokens it uses */
  components?: {
    id: string;
    purpose: string;
    tokens?: string[];
    /** Records whose content the component shows, such as foundation/problem */
    reads?: string[];
  }[];
  /** Where the design system is shown, such as a Claude Design System artifact URL */
  artifact?: string;
};

/** The inputs the choice rests on, by key from marketing/design-system/inputs: mission, problem, icp:<id>, alignment:<id>, market:<product>, founder:<id>, competitor:<name> */
export type MarketingDesignSystemFrom = string[];

/** The planned public site (EE-064): which information is shown where, how (the MDX component), when and for whom, with the reasons, planned from the venture's records by operations/marketing/site/plan.mjs. A marketing record, part of the marketing package handed to engineering (EE-065). Version 0.x, unevaluated. */
export type MarketingSitemap = {
  version: string;
  venture: string;
  name?: string;
  phase?: string;
  planned_at?: string;
  planned_by?: "jev" | "conventions";
  facts: {
    [key: string]: unknown;
  };
  offerings: {
    id: string;
    name?: string;
    offering: "product" | "service" | "platform" | "content" | "marketplace";
    status?: string | null;
    offered_to: string[];
    serves?: string[];
    from?: string;
    [key: string]: unknown;
  }[];
  audience: {
    offered_to: unknown[];
    partner_led: boolean;
    types: unknown[];
    weights?: {
      [key: string]: unknown;
    };
    note?: string;
    [key: string]: unknown;
  };
  pages: {
    path: string;
    parent: string | null;
    label: string;
    type: string;
    level: "home" | "nav" | "linked" | "anywhere";
    sections: {
      item: string;
      label?: string;
      component: string;
      need: number;
      required?: string;
      for: string[];
      why: string[];
      when?: string;
      source: {
        [key: string]: unknown;
      };
      variant: string;
      [key: string]: unknown;
    }[];
    [key: string]: unknown;
  }[];
  omitted: unknown[];
  handoff: {
    to: "engineering";
    note?: string;
    variants?: string[];
    [key: string]: unknown;
  };
  [key: string]: unknown;
};

/** The money package's summary (money/_summary.json, EE-070): cash, monthly flows and runway as of the last sync from the system of record (Rho), the one money record that is versioned and the only one an agent or a trace sees. source says whether it came from Rho's sandbox, a saved fixture, or the founder's live account. */
export type MoneySummary = {
  /** rho-sandbox, rho-live, or a fixture's name */
  source: string;
  business?: string;
  /**
   * @format date-time
   */
  synced_at: string;
  /**
   * @format date-time
   */
  as_of: string;
  window?: {
    /**
     * @format date-time
     */
    from: string;
    /**
     * @format date-time
     */
    to: string;
  };
  cash: {
    /** Minor units (cents for USD), as the source returns them */
    amount: number;
    currency: string;
  };
  monthly_inflow?: {
    /** Minor units (cents for USD), as the source returns them */
    amount: number;
    currency: string;
  };
  monthly_outflow?: {
    /** Minor units (cents for USD), as the source returns them */
    amount: number;
    currency: string;
  };
  monthly_net?: {
    /** Minor units (cents for USD), as the source returns them */
    amount: number;
    currency: string;
  };
  runway_months?: number | null;
  accounts?: number;
  transactions?: number;
  note?: string;
};

/** A venture's overrides to Naive's defaults, at the venture root (P-2, like next.config.js): the gate (fail-closed routes, rules over the router's path patterns, which package rules it imports), function owners, check settings (P-7, like eslint.config.mjs), thresholds, which System 1 questions run, pinned package versions (U-4) and how strictly the acting role is checked (M-18). Every field is optional; a missing one keeps the default in schema/naive-config.mjs. node schema/check-config.mjs <venture dir> checks it. */
export type NaiveConfig = {
  $schema?: string;
  /** The plugin beta's gate (schema/beta-gate.mjs): capabilities in beta/capabilities.json unlock in order, each after checkpoint feedback. Off by default. */
  beta?: {
    enabled?: boolean;
    /** Opt-in for routing feedback through Jev: send lets feedback text leave the machine, and counts only with set_by naming the person who turned it on. A TYPESAFE_API_KEY alone sends nothing. */
    jev?: {
      send?: boolean;
      set_by?: {
        person: string;
        /**
         * @format date-time
         */
        at: string;
      };
    };
  };
  /** Usage telemetry (schema/telemetry.mjs, schema/telemetry.schema.json), opt-in: enabled writes events to .naive/telemetry.jsonl; send lets them leave the machine, and counts only with set_by naming the person who turned it on. */
  telemetry?: {
    enabled?: boolean;
    send?: boolean;
    set_by?: {
      person: string;
      /**
       * @format date-time
       */
      at: string;
    };
  };
  /** The venture's one gate (X-5). It runs before every write and never calls a model (X-4). */
  gate?: {
    /** Routes whose agent writes are always drafts; each covers that route and every route under it (X-3) */
    fail_closed?: string[];
    /** Rules that read the write itself: who writes it, its route, its confidence (X-1, X-2, X-6) */
    rules?: NaiveConfigRule[];
    /** Which packages' gate rules the gate imports from their package definitions (X-5): true for all (the default), false for none, or a map of package name to false to leave one out */
    packages?: boolean | {
      [key: string]: boolean;
    };
    /** Keep differing agent drafts of one record side by side, with one decision for the founder, on every held route (X-2). A rule can turn this on for its routes alone */
    variants?: boolean;
  };
  /** Function owners: function (department) id to the role that owns it, so a write routed to its owner reaches the right person (X-2) */
  owners?: {
    [key: string]: string;
  };
  /** Check settings (P-7): which of a route's checks are off, and which only warn */
  checks?: {
    /** Checks that do not run, by path (schema/check-telos.mjs) */
    off?: string[];
    /** Checks that run but do not fail the route's check */
    warn?: string[];
  };
  /** Investors lint (investors/lint). Each rule is fail-open unless its mode is fail-closed, which makes that rule's findings fail the run. */
  investors_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Thresholds by name: confidence (the gate's confidence routing), idea-map (when a System 1 answer becomes a tag) */
  thresholds?: {
    [key: string]: number;
  };
  /** Which System 1 questions run, by framework (idea-map): off lists question kinds, the part of a question key before the colon (exists, dept.legal, rec.*) */
  questions?: {
    [key: string]: {
      off?: string[];
    };
  };
  /** Pinned package versions (U-4): package name to the version the venture uses. A write to a pinned package whose installed version differs is refused until the pin or the install changes. A pin is a version string, or { version, early, channel } as naive upgrade writes it (U-5) */
  packages?: {
    [key: string]: string | {
      version: string;
      early?: boolean;
      channel?: "stable" | "canary";
    };
  };
  /** How the acting role is checked on every action (M-18) */
  acting?: {
    /** A role id the team plan does not list: allow (the default, it may reach every route) or refuse */
    unknown_roles?: "allow" | "refuse";
  };
  /** The framework version the venture is on, and its channel (EE-076, written by naive upgrade) */
  naive?: {
    version?: string;
    channel?: "stable" | "canary";
  };
  /** Mentura kits whose automations this venture turns on */
  kits?: string[];
  /** The publish lint (schema/publish-lint.mjs): each rule off, warn or error, the marks to flag, and findings a person waived */
  publish_lint?: {
    rules?: { [K in "copy-distance" | "leaks" | "brand" | "claims" | "marks" | "personal-data" | "secrets"]?: "off" | "warn" | "error" };
    marks?: string[];
    waived?: {
      rule: string;
      file?: string;
      text?: string;
      why?: string;
      by?: string;
    }[];
  };
  /** What starts the next step on an event (schema/triggers.mjs) */
  triggers?: unknown[];
  /** Per-rule mode for the product lint (schema/lint-product.mjs, route product/lint). A rule stays fail-open unless its mode is fail-closed. */
  product_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** naive diagnose --if-due: a full diagnosis runs only when the founder's transcripts since the cursor reach threshold estimated tokens (characters / 4), or a new session is older than stale_hours */
  diagnose?: {
    threshold?: number;
    stale_hours?: number;
  };
  /** The premise-attack linter (schema/premise-lint.mjs): each rule, one per aspect, is off, warn (the default) or error */
  premise_lint?: {
    rules?: {
      "undefined-term"?: "off" | "warn" | "error";
      unmeasurable?: "off" | "warn" | "error";
      "no-owner"?: "off" | "warn" | "error";
      "unsupported-premise"?: "off" | "warn" | "error";
      orphan?: "off" | "warn" | "error";
      conflict?: "off" | "warn" | "error";
      dependency?: "off" | "warn" | "error";
      "phase-mismatch"?: "off" | "warn" | "error";
    };
  };
  /** Per-rule mode for the money lint (schema/lint-money.mjs, route money/lint). A rule stays fail-open unless its mode is fail-closed. */
  money_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Customers lint (customers/lint). Per rule, mode fail-closed makes that rule's findings exit 1. The default is fail-open. */
  customers_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Per-rule mode for the validation lint (schema/lint-validation.mjs, route validation/lint). A rule stays fail-open unless its mode is fail-closed. */
  validation_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** finance/lint (schema/lint-finance.mjs). Each rule warns and stays fail-open unless its mode is fail-closed, which makes its findings exit 1. */
  finance_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Per-rule mode for the legal lint (schema/lint-legal.mjs, route legal/lint). A rule stays fail-open unless its mode is fail-closed. */
  legal_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Foundation lint (foundation/lint): per-rule mode overrides. A rule stays fail-open unless its mode is fail-closed. */
  foundation_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
  /** Per-rule mode for the people lint (schema/lint-people.mjs, route people/lint). A rule stays fail-open unless its mode is fail-closed. */
  people_lint?: {
    rules?: {
      [key: string]: {
        mode?: "fail-open" | "fail-closed";
      };
    };
  };
};

export type NaiveConfigRule = {
  id: string;
  /** The routes the rule covers, in the router's own path patterns (X-6): a route (validation/pricing), an [id] segment (money/[id]), * for one segment and ** for any depth (validation/**, which covers validation too) */
  routes: string[];
  /** Who it applies to; default agents only */
  actors?: ("agent" | "person")[];
  /** Team-plan roles it applies to; default every role */
  roles?: string[];
  when?: {
    /** Applies when the write carries a confidence score below this number, or below the named threshold. The score is computed before the write; a write with no score never matches */
    confidence_below?: number | string;
    /** Applies only when the record already exists (true) or does not yet (false) */
    exists?: boolean;
  };
  /** draft: hold it as a draft; owner: hold it as a draft sent to the function owner; refuse: do not write it */
  then: "draft" | "owner" | "refuse";
  /** The owner a routed write goes to; default the function owner in owners, else the record's decision-class owner, else founder */
  owner?: string;
  /** Keep differing drafts side by side under one decision (X-2) */
  variants?: boolean;
  note?: string;
};

/** Whether each concept of the Next.js translation ledger is built, and the docs page that explains it. Checked by schema/check-nextjs-status.mjs. */
export type NextjsStatus = {
  about: string;
  /**
   * @format date
   */
  checked: string;
  rows: {
    id: string;
    chapter: string;
    status: "built" | "partial" | "not built" | "n/a";
    evidence?: string[];
    page?: string;
    note?: string;
  }[];
};

/** Who owns the venture and on what terms, at <venture>/governance/ownership.json (EE-022): share classes and the rights each carries, holders, grants with vesting, the option pool, and unpriced instruments such as SAFEs. It is a record of what was agreed, not the legal document: the signed documents are the truth, and decisions to change this file are founder decisions made with counsel (decision class ownership-or-control). schema/check-governance.mjs checks it; schema/payouts.mjs computes payouts from it. */
export type Ownership = {
  /**
   * @format date
   */
  updated: string;
  /** shares for a corporation, units for an LLC, percent for a partnership or an informal split */
  unit: "shares" | "units" | "percent";
  currency?: string;
  classes: {
    id: string;
    name?: string;
    /** common and units are paid last; preferred carries a liquidation preference */
    kind: "common" | "preferred" | "units";
    /** 1 by default; more than 1 for super-voting (dual-class) shares, 0 for non-voting */
    votes_per_share?: number;
    /** Original issue price; the basis of a liquidation preference */
    price_per_share?: number;
    liquidation?: {
      /** 1 is standard (1x) */
      multiple?: number;
      /** true: takes its preference and then shares the rest; false (standard): takes the greater of its preference or what it would get as common */
      participating?: boolean;
      /** Higher is paid first; equal ranks share pro rata (pari passu) */
      seniority?: number;
    };
    /** Investor rights this class carries */
    rights?: ("board-seat" | "board-observer" | "information" | "pro-rata" | "protective-provisions" | "anti-dilution-broad-based" | "anti-dilution-full-ratchet" | "drag-along" | "tag-along" | "right-of-first-refusal" | "co-sale" | "registration" | "redemption")[];
  }[];
  holders: {
    id: string;
    name: string;
    /** pool is the reserved option pool: its unissued amount is paid nothing */
    kind: "founder" | "employee" | "advisor" | "investor" | "pool" | "other";
    /** The venture role they hold, if any */
    role?: string;
    /** Path to their signed agreement (advisor, employee, investment) */
    agreement?: string;
  }[];
  grants: {
    holder: string;
    class: string;
    amount: number;
    /**
     * @format date
     */
    granted?: string;
    vesting?: {
      /**
       * @format date
       */
      start: string;
      /** 48 is common for founders and employees, 24 for advisors */
      months: number;
      /** 12 is common */
      cliff_months?: number;
      acceleration?: "none" | "single-trigger" | "double-trigger";
    };
  }[];
  instruments?: {
    id: string;
    holder: string;
    kind: "safe-post-money" | "safe-pre-money" | "convertible-note";
    amount: number;
    /**
     * @format date
     */
    signed?: string;
    valuation_cap?: number;
    discount?: number;
    /** The class it converts into at the next priced round */
    converts_to?: string;
    rights?: ("board-seat" | "board-observer" | "information" | "pro-rata" | "protective-provisions" | "anti-dilution-broad-based" | "anti-dilution-full-ratchet" | "drag-along" | "tag-along" | "right-of-first-refusal" | "co-sale" | "registration" | "redemption")[];
  }[];
};

/** The venture's people (people/people.json): who is in it, in which role, and which functions (hats) each owns. It is to human capital what venture.json is to the venture. A founder also has a file in people/founders/. Names only: no personal details. */
export type People = {
  venture: string;
  /** solo: one person owns every function the venture imports */
  mode: "solo" | "team";
  people: {
    id: string;
    name: string;
    /** A role id from governance/venture-template/roles/venture-roles.json */
    role: string;
    /** The functions this person owns. In the structured layout (EE-086) hats are read from the org chart in venture.json and not stored here */
    hats?: ("strategy" | "products" | "marketing-and-sales" | "supply-chain" | "service-delivery" | "customer-service" | "human-capital" | "it" | "finance" | "assets" | "risk-and-compliance" | "external-relationships" | "capabilities")[];
    founder_file?: string;
  }[];
  /** The founder agreement, once there is one (governance/founder-agreement.json) */
  founder_agreement?: string;
  /**
   * @format date
   */
  updated?: string;
};

/** A step-by-step guide a venture function runs, in conversation with the founder (a template is the empty shape of one record; a playbook is the order of the work). Each step says what the agent is trying to learn, how to hold the conversation, which records it writes and when the step is done. An agent proposes; the founder confirms what is written. */
export type Playbook = {
  id: string;
  title: string;
  /** What the founder has at the end */
  purpose: string;
  /** When an agent should offer this playbook */
  when: string;
  /** The venture function that owns it */
  function?: string;
  phase?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  /** Ideas the playbook is built on */
  sources?: string[];
  steps: {
    id: string;
    title: string;
    /** What the agent is trying to learn or settle */
    goal: string;
    /** How to hold the conversation: questions, moves, what to avoid */
    conversation: string[];
    writes?: {
      route: string;
      as?: "draft" | "proposal" | "evidence" | "decision";
      note?: string;
    }[];
    done_when: string;
    /** The view to build for the founder at this step, per the choosing-artifacts skill */
    artifact?: string;
  }[];
};

/** One product of a venture, stored as a card at products/<id>.json (EE-011). It holds the product's own market, job, technology, offering and business model; Product Anatomy judges it against the venture's core and assigns its portfolio role per phase. */
export type Product = {
  id: string;
  name: string;
  description: string;
  /** Who is served (Abell: customer groups). One market, or several with one marked primary. */
  market?: {
    customer?: "b2c" | "b2b" | "b2g" | "b2b2c";
    /** How the people in this market stand to the product (EE-021): customer buys, client is served under a professional relationship, user uses (may not pay), member belongs, audience reads, watches or listens, partner works with the venture */
    relationship?: "customer" | "client" | "user" | "member" | "audience" | "partner";
    segment?: string;
    geography?: string;
    /** true: one industry; false: across many (horizontal) */
    vertical?: boolean;
  } | {
    customer?: "b2c" | "b2b" | "b2g" | "b2b2c";
    segment?: string;
    geography?: string;
    /** true: one industry; false: across many (horizontal) */
    vertical?: boolean;
    /** The market the product is mainly built for; exactly one when several are listed */
    primary?: boolean;
  }[];
  /** The need it meets (Abell: customer function; jobs to be done) */
  job?: string;
  /** How it meets the need (Abell: alternative technologies) */
  technology?: string;
  /** What AI is to the product. feature: the product works without the model. ai-harness: the product is the software around a model (a chatbot); remove the model and nothing is left. agent-harness: an AI harness where the model directs its own steps and tool use toward a goal. Tests in docs/ontology.md. */
  ai?: "none" | "feature" | "ai-harness" | "agent-harness";
  offering?: "product" | "service" | "platform" | "content" | "marketplace";
  /** Where in the system the product works: the whole system, one layer, or one tier of the operations layer. Kits use it most (a knowledge-layer kit, a delivery-tier kit). */
  scope?: {
    level: "system" | "layer" | "tier";
    layer?: "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface";
    tier?: "governance" | "delivery" | "software-engineering" | "automation";
  };
  /** Kits this product is bundled into, by product id in the same venture. A part can still be its own product with its own market and portfolio role. */
  part_of?: string[];
  /** Pattern ids from schema/vocab/business-models.json: the St. Gallen Business Model Navigator's 55 (subscription, freemium, add-on and so on) plus named extras such as open-core */
  business_model?: string[];
  /** The first phase in which it may lead (a standing decision can hold a product back) */
  allowed_from?: "validation" | "beachhead" | "scale" | "platform";
  /** Products this one sends users, data or revenue to; Product Anatomy computes spillover from these */
  flows_to?: string[];
  status?: "idea" | "building" | "live" | "retired";
  /** The product is, or contains, software the venture builds. Such a product needs a repository, so its venture (or a parent) lists one in repos (EE-020) */
  software?: boolean;
  /** The id of the repository in the venture's (or a parent's) repos that holds its code */
  repo?: string;
  /** The ICP profiles (purpose/icp.json ids) the product is offered to: who buys or adopts it, and so whom its marketing addresses first (EE-064). In a B2B2C or partner-led venture these are the partners, not the partners' customers. */
  offered_to?: string[];
  /** What the product does. Each feature names the job it serves: a job of an ICP profile in offered_to. The jobs stay on the ICP record and are read by id, not copied here. */
  features?: {
    id: string;
    name?: string;
    /** The job this feature serves. It must be a job of an ICP profile this product is offered to. */
    job?: string;
  }[];
  /** ICP profiles the product ultimately serves through those it is offered to, such as a partner's own customers (EE-064) */
  serves?: string[];
};

/** The library of attributes a founder profile can add, each with the types its entries may take, and the templates that start a profile from a set of them. */
export type ProfileAttributes = {
  version: string;
  note?: string;
  attributes: {
    id: string;
    label: string;
    /** How a mentor opens it */
    question: string;
    types?: string[];
  }[];
  templates: {
    id: string;
    label: string;
    attributes: string[];
  }[];
};

/** One line of a venture's provenance log (<venture>/provenance.jsonl, EE-031), after W3C PROV: the entity (a record file) was generated by an activity, attributed to an agent (a person or an AI agent), derived from other entities, under a decision. The log is append-only: each line carries the hash of the line before, so an edited or deleted line breaks the chain. Git history is the implicit provenance for anything written outside the log. schema/check-provenance.mjs checks it. */
export type ProvenanceEntry = {
  /**
   * When the activity ended (prov:endedAtTime)
   * @format date-time
   */
  at: string;
  /** The file written, relative to the venture folder (prov:Entity); for a record kept in another source (EE-037), its address <source>://<path> */
  entity: string;
  /** The route the write went through, when it went through the router */
  route?: string;
  /** write: written in place. draft: an agent's write to a gated record, held in _drafts/, or any write to a source that takes writes by pull request, held there until the pull request is merged. accept: a person accepted a draft. baseline: a record that existed before the log, adopted with its current content (prov:Activity). confirm: a person confirmed one guiding statement in the record, by typing its id (EE-051); the content is unchanged. move: a file moved to a new path; derived_from names the old path. release: a set of moves recorded as one release. publish: an artifact's built output went out on a channel (entity is the output, the decision names the publish decision). rollback: the previous version was restored merge: a person (or a role a delegation grant allows) applied a decided decision version to the records it decides; the decision file is the entity. */
  activity: "write" | "draft" | "accept" | "baseline" | "confirm" | "move" | "release" | "publish" | "rollback" | "merge";
  /** Who acted (prov:wasAttributedTo / prov:wasAssociatedWith) */
  agent: {
    /** unverified: a door with no sign-in said a person acted; the id is a claimed name */
    kind: "person" | "agent" | "unverified";
    /** A person's name or handle, or an agent's role id from the team plan */
    id?: string;
    /** The account a door with sign-in checked for this person */
    account?: string;
    /** An AI agent's model */
    model?: string;
    /** A link or id for the session that acted */
    session?: string;
    /** The agent harness, such as Claude Code or Cursor, as it named itself */
    harness?: string;
    /** The interface the write came through */
    via: "cli" | "mcp" | "api" | "router" | "console";
  };
  /** What the content came from: venture-relative paths, URLs or decision ids (prov:wasDerivedFrom) */
  derived_from?: string[];
  /** The decision or decision class the activity acted under, such as EE-026 or ownership-or-control */
  decision?: string;
  note?: string;
  /** For a record kept outside the venture folder (EE-037): the source it was written to, its version there, and the commit or pull request that holds it */
  source?: {
    /** The source id from the venture's knowledge/sources.json */
    id: string;
    connector: string;
    /** The git blob SHA-1 of the content as written */
    version: string;
    commit?: string;
    /**
     * The pull request that accepts the write when it is merged
     * @format uri
     */
    pull_request?: string;
  };
  /** Hash of the file's content as written */
  sha256: string;
  /** The previous line's hash, or genesis for the first line */
  prev: string;
  /** sha256 of prev followed by this line without its hash field, as JSON with sorted keys */
  hash: string;
  /** confirm only: the id of the guiding statement confirmed (purpose/guiding-statements.json) */
  statement?: string;
};

/** The register of what the venture ships as it is, at public/assets.json (I-23, J-2, J-3, J-4): each file in public/ with its source, license and credit, facts read by code from its bytes, and alt text with who wrote it; remote images as links with a note in raw/sources/<id>/; and remote_hosts, the hosts an agent may fetch from. Checked by schema/check-assets.mjs. Version 0.x, unevaluated. */
export type PublicAssets = {
  version: string;
  /** Hosts an agent may fetch images from (exact, or *.example.com); the platform fetcher refuses any other */
  remote_hosts?: string[];
  assets: {
    path: string;
    /** Where it came from: who made it, or a URL */
    source: string;
    /** An SPDX id (CC-BY-4.0, OFL-1.1), owned (made by or for the venture), licensed (bought), or the restriction (all-rights-reserved) */
    license: string;
    /** Who to credit; a missing credit fails the check */
    credit?: string;
    alt?: PublicAssetsAlt;
    /** An image that says nothing, so it needs no alt text */
    decorative?: boolean;
    /** The remote work this is a copy of */
    origin_url?: string;
    /** The design system (brand design_systems id) this came from */
    design_system?: string;
    facts?: PublicAssetsFacts;
  }[];
  /** Remote images the venture links to rather than ships */
  remote?: {
    /** The raw source holding the note: raw/sources/<id>/ */
    id: string;
    url: string;
    license: string;
    credit?: string;
    alt?: PublicAssetsAlt;
    /** Facts from a fetch by the platform; the original stays private in raw/sources/<id>/original.* */
    fetched?: PublicAssetsFacts;
    /** Where a full copy was kept, only when the license allows it */
    copy?: string;
  }[];
};

export type PublicAssetsAlt = {
  text: string;
  /** Who wrote it. An agent's alt text stays pending until a person confirms it in provenance */
  by: "agent" | "person";
};

/** Read from the bytes by code (schema/assets.mjs), never written by hand */
export type PublicAssetsFacts = {
  type: string;
  width?: number;
  height?: number;
  sizes?: string[];
  bytes: number;
  sha256: string;
  filled_at?: string;
};

/** Where a venture publishes and who may publish what there, at <venture>/governance/publication-policy.json (EE-025). Every publication passes the gate: it runs as a handoff under the public-commitment decision class, names its channel, passes the channel's checks and preview, and is approved by a person. Agents may draft and check; they never approve. */
export type PublicationPolicy = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  note?: string;
  /** Groups that draft or approve, such as a marketing team or a governance team. Members are role ids from the role registry. */
  teams?: {
    id: string;
    name?: string;
    pillar?: "product" | "brand" | "business";
    members: string[];
  }[];
  /** The rules a publication must follow: the venture's own (brand guidelines, editorial guidelines) and outside ones (a platform's rules, advertising or disclosure law). */
  guidelines?: {
    id: string;
    title: string;
    kind: "brand" | "editorial" | "legal" | "platform" | "disclosure" | "security" | "other";
    /** Pillar or role that keeps it */
    owner?: string;
    /** Relative to the venture folder */
    path?: string;
    url?: string;
    /**
     * When an outside guideline's URL was last checked
     * @format date
     */
    checked?: string;
  }[];
  channels: {
    id: string;
    name: string;
    kind: "website" | "docs-site" | "blog" | "social" | "newsletter" | "email" | "app-store" | "press" | "investor-update" | "regulatory-filing" | "open-source-repository" | "other";
    /** Where it lands: a URL, an account, a repository or a recipient list */
    destination: string;
    audience?: string;
    /** Guideline ids that apply here */
    guidelines?: string[];
    /** Who may publish what on this channel */
    rules: {
      /** The kind of content, e.g. methodology pages, release notes, a funding announcement */
      content: string;
      /** The layers whose records it may publish */
      from_layers?: ("purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface")[];
      /** Role or team ids; agents may draft */
      drafters?: string[];
      /** Role or team ids; at least one is a person, and no agent approves */
      approvers: string[];
    }[];
    checks: {
      id: string;
      /** A command run from the repository root; for a review, what the reviewer checks */
      check: string;
      kind?: "conformance" | "review";
    }[];
    /** How to see exactly what would go out before it does, e.g. a dry run */
    preview: string;
    /** The channel's tool configuration, relative to the venture folder (e.g. the publisher's allowlist) */
    config?: string;
    /** The third-party platform the channel runs on, if any. A channel on a platform cites that platform's rules (a guideline of kind platform) */
    platform?: "substack" | "medium" | "x" | "facebook" | "instagram" | "threads" | "linkedin" | "youtube" | "tiktok" | "reddit" | "bluesky" | "mastodon" | "discord" | "app-store" | "google-play" | "github" | "other";
    /** Required on social, newsletter and blog channels: replies, comments and direct messages speak for the venture in public. gated means each reply passes the gate like any publication; delegated means named people may reply within the guidelines without a handoff each time; none means the venture does not reply there */
    replies?: {
      mode: "gated" | "delegated" | "none";
      /** Role or team ids, when delegated; each must include a person */
      delegates?: string[];
      note?: string;
    };
  }[];
};

/** Every place a venture has published (governance/publications.json): one entry per channel and artifact, naming the channel in governance/publication-policy.json, the artifact that was published (artifacts are what get published, records never are), where it went, the sha256 of the built output, the person who approved it, when, the versions before it (for naive publish rollback) and any embargo. node schema/check-publications.mjs fails when something is live without an entry, when an entry's sha256 does not match the built output, or when an entry has no approver. */
export type Publications = {
  venture?: string;
  entries: {
    /** A channel id in governance/publication-policy.json */
    channel: string;
    /** The artifact id (artifacts/<id>.json) that is published */
    artifact: string;
    /** Where it is published */
    url?: string;
    kind?: "site" | "claude-artifact" | "social" | "docs" | "email" | "newsletter" | "app-store" | "other";
    /** The public MDX variants that compile to it, venture-relative */
    sources?: string[];
    /** The built output, venture-relative, as naive publish build wrote it */
    output?: string;
    /** The sha256 of the built output that is live */
    sha256?: string;
    /** The person who approved this version. Never an agent. */
    approved_by?: string;
    /**
     * When this version went live
     * @format date-time
     */
    at?: string;
    /** The publish decision record that approved it (decisions/<file>) */
    decision?: string;
    door?: "one-way" | "two-way";
    /**
     * An embargo: the gate refuses to publish before this time
     * @format date-time
     */
    not_before?: string;
    /** A record it was built from changed since it was published; rebuild, re-lint and republish */
    stale?: boolean;
    /** Earlier live versions, newest first; naive publish rollback restores the first */
    previous?: {
      sha256: string;
      output?: string;
      approved_by?: string;
      /**
       * @format date-time
       */
      at?: string;
      decision?: string;
    }[];
  }[];
};

/** Where a founder-supplied source came from, at raw/sources/<id>/source.json (EE-070). text.md is the text. original.* stays out of git. Raw is immutable. */
export type RawSource = {
  id: string;
  /** Where this source came from: a url, a person, or a note such as founder-supplied */
  origin: string;
  title?: string;
  /**
   * @format date
   */
  fetched?: string;
};

/** A layer's references (EE-014): the sources behind its opinionated defaults and the alternatives it considered. One file per layer at <layer>/references/references.json. A URL is recorded when one exists and re-checked; the find-reference skill fills gaps from title, authors and year. */
export type Reference = {
  layer: "purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface";
  references: {
    id: string;
    title: string;
    authors: string[];
    year: number;
    kind: "book" | "article" | "paper" | "standard" | "law" | "dataset" | "conversation";
    summary: string;
    /**
     * @format uri
     */
    url?: string;
    /**
     * When the url last resolved
     * @format date
     */
    checked?: string;
    informs: string[];
    stance: {
      is: "adopted" | "adapted" | "alternative" | "rejected";
      why: string;
    };
  }[];
};

/** A canonical requirement, at <venture>/foundation/requirements/<id>.json: something that must hold, derived from goals or their measures, by a phase, constraining named functions and verified by a check, evidence or a person. Read by validation and the decision index; framework-neutral. */
export type Requirement = {
  id: string;
  venture?: string;
  statement: string;
  /** Goal ids or measure ids (goal/measure or a bare measure id) */
  derives_from: string[];
  must_hold_by?: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  /** Function ids from venture.json functions */
  constrains?: string[];
  verified_by?: {
    kind: "check" | "evidence" | "person";
    ref?: string;
  };
  weight?: number;
  framework?: string;
  updated?: string;
  /** The founder's messages this record was made from (naive diagnose catches) */
  conversation?: ConversationRef[];
};

/** One role a venture can install, at governance/venture-template/roles/<id>.json. The founder is the chief delegator and holds all authority; every other role holds only what is granted to it in governance/delegation.json, and only from the classes it lists as grantable. Its work is verified by another role (verified_by), never by itself; only the chief delegator has no verifier. Checked by schema/check-delegation.mjs. */
export type RoleTemplate = {
  /** Matches the file name */
  id: string;
  name: string;
  /** Other names for this role (such as cto for architect); the id is canonical and matches agent-roles.json and decision-rights.json */
  aliases?: string[];
  /** True for the founder only: the root of every delegation chain */
  chief_delegator?: boolean;
  /** The function the role serves, such as product, engineering, marketing, or all */
  function: string;
  description?: string;
  /** Decision classes (from decision-rights.json) this role may be granted; the chief delegator lists none, since it holds all */
  grantable_classes: string[];
  default_tier: "person" | "frontier" | "workhorse" | "none";
  /** Lint routes it runs, such as marketing/brand-lint */
  lint_suites: string[];
  /** The role that verifies its work; null only for the chief delegator */
  verified_by: string | null;
  /** Further verifiers for some work, such as the founder for spend */
  also_verified_by?: string[];
  /** Path from the repository root to the role's skill */
  skill: string;
};

/** Renamed routes (EE-032). Routes are an API that agents and scripts depend on, so a renamed record keeps its old route as an alias: the router follows it and answers with a deprecation note. Remove an alias only after the version it was deprecated in has been out for a release. interface/test.mjs checks that every alias points at a route that exists. */
export type RouteAliases = {
  aliases: {
    /** The old route */
    from: string;
    /** The route it became */
    to: string;
    /**
     * @format date
     */
    since: string;
    /** Why it moved, cited by decision id */
    note?: string;
  }[];
};

/** Naive's knowledge of the software development life cycle (R-26), after ISO/IEC/IEEE 12207: process groups, processes, activities and tasks, each task with the decision classes it needs, the phase it is first needed in and its owning role. It holds no execution detail: MAD owns how (R-27) and the agent router owns who does it (R-25). A task is referred to as <mad_module>/<activity>/<task>, the form MAD's method-request uses. Checked across files by schema/check-sdlc-catalog.ts. */
export type SdlcCatalog = {
  sdlc_catalog: "0.2.0";
  version: string;
  standard: string;
  note?: string;
  groups: {
    id: "agreement" | "organizational-project-enabling" | "technical-management" | "technical";
    name: string;
    processes: {
      id: string;
      name: string;
      clause: string;
      /** The venture function (one of the 13 APQC categories in operations/departments.json) whose work this process is. The software processes are mostly the products function's; operating the software is IT's, and the organizational processes belong where APQC files them. The check makes sure it names a department. */
      function: string;
      /** Technical processes only: the MAD process module that routes its methods, or null when it is not MAD's (business or mission analysis is the product function's). */
      mad_module?: "requirements" | "system-design" | "implementation" | "integration" | "verification" | "transition" | "validation" | "operation" | "maintenance" | null;
      /** Other groups: the MAD layer whose questions cover how it is run. */
      mad_layer?: "governance" | "delivery" | "software-engineering" | "automation";
      owner_role: string;
      note?: string;
      activities?: {
        id: "prepare" | "perform" | "manage-results";
        name: string;
        tasks: {
          id: string;
          name: string;
          /** Decision classes the task needs, from the venture's decision rights. */
          decision_classes: string[];
          /** The earliest phase in which a venture building software needs this task. */
          needed_from: "discovery" | "validation" | "beachhead" | "scale" | "platform";
          /** The role that owns the task's decisions, a role template id. */
          owner_role: string;
        }[];
      }[];
    }[];
  }[];
};

/** How present a venture's public records are on its marketing site, weighed by who the site must speak to now (EE-062, EE-063). Written by operations/marketing/site/presence.mjs from a read of the site; version 0.x, ours and unevaluated. */
export type SitePresence = {
  version: string;
  site: string;
  venture?: string | null;
  read_via?: "firecrawl" | "fetch";
  read_at?: string;
  judged_by: "jev" | "keywords";
  facts: {
    [key: string]: unknown;
  };
  score: number;
  audiences: {
    [key: string]: {
      weight: number;
      score?: number | null;
      [key: string]: unknown;
    };
  };
  pages: {
    path: string;
    title?: string;
    type: string;
    level: "home" | "nav" | "linked" | "anywhere";
    [key: string]: unknown;
  }[];
  items: {
    id: string;
    label: string;
    record: string;
    need: number;
    required: "home" | "nav" | "linked" | "anywhere";
    for?: string[];
    at?: "home" | "nav" | "linked" | "anywhere" | null;
    score: 0 | 0.5 | 1;
    found?: unknown[];
    note: string;
    /** Who needs the item and why: each audience's weight, the item's importance to it, and the reason (for customers, from the customer types) */
    evidence?: {
      audience: string;
      weight?: number;
      importance?: number;
      need: number;
      why: string;
      source: "customer types" | "matrix";
      [key: string]: unknown;
    }[];
    [key: string]: unknown;
  }[];
  fix_first: string[];
  /** Who the site is for and where that comes from: the founder's words, the venture's ICP record, or inferred from the home page; and the customer types Jev placed it in */
  icp: {
    text: string;
    source: "founder" | "record" | "inferred";
    cite: string;
    types: {
      id: string;
      label: string;
      p?: number | null;
      [key: string]: unknown;
    }[];
    [key: string]: unknown;
  };
  /** The site's routes as a tree from the home page, each rated on the items that belong there; ghost routes are pages the venture's priorities call for that the site lacks */
  sitemap: {
    path: string;
    parent: string | null;
    label: string;
    type: string;
    level: "home" | "nav" | "linked" | "anywhere";
    read: boolean;
    rating: number | null;
    expected: string[];
    found: string[];
    missing: string[];
    ghost?: boolean;
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
};

/** The framework's map of strategic foundation (EE-051): per question of the Five Ws and How plus whether, the record attributes that answer it. */
export type StrategicFoundation = {
  version: string;
  note?: string;
  questions: {
    id: string;
    ask: string;
    statements: {
      id: string;
      record: string | null;
      attribute: string | null;
      /** The id of another statement this one is derived from; it takes that statement's status and value */
      derived_from?: string;
      note?: string;
      [key: string]: unknown;
    }[];
    [key: string]: unknown;
  }[];
  [key: string]: unknown;
};

/** Declares one append-only stream under a data package's _streams/<id>/ (EE-070). sensitive true means the stream's events stay out of git and only summary.md is versioned. */
export type Stream = {
  id: string;
  sensitive: boolean;
  /** What the versioned summary.md covers, when sensitive is true */
  summary?: string;
};

/** The systems of record create-venture offers per function (schema/systems-catalog.json): each system's kind, what its address looks like, and the code that connects to it, if any. */
export type SystemsCatalog = {
  version: string;
  note?: string;
  systems: {
    [key: string]: {
      label: string;
      kind: string;
      address: string;
      connect: string | null;
    };
  };
  functions: { [K in "strategy" | "products" | "marketing-and-sales" | "supply-chain" | "service-delivery" | "customer-service" | "human-capital" | "it" | "finance" | "assets" | "risk-and-compliance" | "external-relationships" | "capabilities" | "legal"]?: string[] };
};

/** Who the venture needs, agent or person, when, with what authority, and where a human stays in the loop (EE-029), at <venture>/operations/team-plan.json. Tasks cite the agent capability register; recruiting briefs say what each open person role is for. */
export type TeamPlan = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  note?: string;
  roles: {
    /** A role id from the role registry, or the venture's own */
    id: string;
    /** Required for a role not in the registry */
    name?: string;
    occupant: "agent" | "person";
    needed_by: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    status: "filled" | "open" | "planned";
    why?: string;
    /** Decision classes delegated to this role */
    authority?: string[];
    tasks?: {
      capability: string;
      /** The person role that decides, reviews or does the part agents cannot */
      human_loop?: string;
    }[];
    /** The routes this role may reach (robots, EE-032), as globs over routes such as purpose/** or purpose/product/*. Left out, the role may reach every route; gates still apply. When given, read defaults to every route and write to none. */
    routes?: {
      read?: string[];
      write?: string[];
    };
  }[];
  recruiting?: {
    role: string;
    kind?: "cofounder" | "hire" | "contractor" | "advisor" | "investor";
    /** A recruiting brief, relative to the venture folder */
    brief: string;
    channels?: string[];
    /** The agent role that drafts, searches and screens */
    assisted_by?: string;
  }[];
};

/** One usage event, one line of <venture>/.naive/telemetry.jsonl; the one schema the plugin beta and Mentura share. Opt-in only (telemetry.enabled in naive.config.json). An event carries no record contents and no _private path: only which capability ran, when, for how long and how it ended. It leaves the machine only when telemetry.send is true and a person set it (schema/telemetry.mjs). */
export type Telemetry = {
  /** The event, e.g. route.write, beta.unlock */
  name: string;
  /** A capability id from beta/capabilities.json, or core */
  capability: string;
  /**
   * @format date-time
   */
  at: string;
  /** A salted hash of the venture id, never the id; the salt stays in the venture's .naive/telemetry-salt and is never sent */
  venture: string;
  session: string;
  duration_ms?: number;
  outcome: "ok" | "error" | "refused" | "cancelled";
  source?: "plugin-beta" | "mentura";
};

/** The end a venture exists to reach, at <venture>/purpose/telos.json (EE-023): start with the end. It states the end state, how anyone would know it was reached (measures), what the owners intend to happen when it is reached (owner outcome), and, for each phase of the Succession Matrix, the exit criteria that must be true to leave it, each serving at least one measure. Other layers read it instead of asking again: the governance layer's exit.json prefers the owner outcome's path, and MAD's governance tier takes its success measure from the primary measure. schema/check-telos.mjs checks it. Written by the owner; an agent may draft it but not settle it. */
export type Telos = {
  /** The end, in one sentence: what the venture is for when it has done its job */
  statement: string;
  /** What is true in the world when the end is reached */
  end_state: string;
  /** The year the end should be reached by, or 'open' */
  horizon?: number | string;
  measures: {
    id: string;
    statement: string;
    target?: string;
    /** The kind of measure; the first six match MAD's success_measure answers, impact is a change in the world beyond the venture */
    kind: "revenue" | "usage_or_adoption" | "cost_or_time_saved" | "compliance_met" | "learning" | "flow_and_lead_time" | "impact";
    /** Exactly one measure is primary */
    primary?: boolean;
  }[];
  owner_outcome: {
    /** What the owners intend to happen once the end is reached; hold means they keep it */
    path: "acquisition" | "ipo" | "secondary-sale" | "merger" | "management-buyout" | "wind-down" | "hold";
    why?: string;
  };
  /** Per phase, what must be true to leave it; refines that phase's generic gate in purpose/frameworks/product-anatomy/phases.json for this venture */
  phases?: {
    phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    exit_criteria: {
      id: string;
      statement: string;
      /** Measure ids this criterion moves the venture toward */
      serves: string[];
      /** How it is shown: a check command, an evidence record, or a metric */
      evidence?: string;
      /** Set when a person says the criterion is met (naive phase --meet); the gate to the next phase passes when every criterion of the current phase has it */
      met?: {
        /**
         * @format date-time
         */
        at: string;
        /** The person who said it is met */
        by: string;
        /** What shows it: a record, a metric, a check */
        evidence?: string;
      };
    }[];
  }[];
  /** How the venture decides to start, keep going or stop, when it reviews that, and what happens when evidence says the direction is wrong (EE-040; MAD's governance tier reads these as go_decision, review_cadence and change_of_direction). Who may make each call is in the decision rights: continue-or-stop and change-direction. */
  steering?: {
    /** test-hypotheses-first: assumptions are written down and tested with real people before committing. business-case-upfront: a case is approved before work starts. owner-judgment: the owner decides as they go. last-responsible-moment: commitments wait until delay costs more than deciding. */
    go_decision?: "test-hypotheses-first" | "business-case-upfront" | "owner-judgment" | "last-responsible-moment" | "other";
    /** When the decision to continue is reviewed: after each experiment or customer test, at each release or milestone, on a calendar, continuously from watched measures, or never formally */
    review?: "per-experiment" | "per-release" | "fixed-period" | "continuous" | "none";
    /** For fixed-period: the period, such as quarterly */
    review_period?: string;
    /** pivot-on-evidence: changing the product, customer or model is expected and planned for. formal-change-control: a change request the deciders approve or reject. owner-decides: the owner adjusts as they see fit. public-proposal: anyone proposes in public and maintainers decide by a published rule. */
    change_of_direction?: "pivot-on-evidence" | "formal-change-control" | "owner-decides" | "public-proposal" | "other";
    note?: string;
  };
};

/** What starts the next step when something happens in a venture (M-12), as React's event handlers and effects trigger actions. An event is a line of the venture's provenance log: a record written, drafted, accepted, confirmed or moved. A trigger lives in naive.config.json triggers, or in a Mentura kit's automations; a kit's automation also names the package it needs, and runs only once that package is complete. A run that fails is recorded and raised as a decision for the founder, never lost (E-7). schema/triggers.mjs runs them. */
export type Trigger = {
  id: string;
  /** Which provenance entries start it; every field given must match */
  on: {
    activity?: "write" | "draft" | "accept" | "baseline" | "confirm" | "move" | "release" | ("write" | "draft" | "accept" | "baseline" | "confirm" | "move" | "release")[];
    /** A glob over the entry's route, such as foundation/** */
    route?: string;
    /** A glob over the file the entry names */
    entity?: string;
    /** Only entries by a person, or only by an agent */
    by?: "person" | "agent";
  };
  /** The next step: one router call, or a decision proposed for a person */
  run: {
    route?: string;
    action?: "read" | "check" | "run" | "write" | "layout" | "view";
    input?: unknown;
    /** A decision record (decision-record.schema.json) proposed for a person to decide */
    propose?: {
      [key: string]: unknown;
    };
  } & ({
    route: string;
    action: "read" | "check" | "run" | "write" | "layout" | "view";
  } | {
    /** A decision record (decision-record.schema.json) proposed for a person to decide */
    propose: {
      [key: string]: unknown;
    };
  });
  /** The package that must be complete first (required for a kit's automation) */
  needs?: string;
  /** Run it once only; later events do not start it again */
  once?: boolean;
  enabled?: boolean;
  note?: string;
};

/** Naive's versions, the migrations between them, and each package's version and channel (schema/upgrades.json, EE-076). naive upgrade reads it from the installed copy. A migration rewrites a venture's records when the framework or one package changes, like a Next.js codemod; a version's guide is bundled in docs/upgrades/. */
export type UpgradeRegistry = {
  /** The installed framework version */
  framework: string;
  note?: string;
  channels?: {
    [key: string]: string;
  };
  versions: {
    version: string;
    /**
     * @format date
     */
    date: string;
    summary: string;
    /** The upgrade guide for this version, a repository path, or null for the first version */
    guide: string | null;
    /** Framework migrations that move a venture onto this version, in order */
    migrations: string[];
  }[];
  migrations: {
    id: string;
    /** A module exporting id, describe and apply(dir, ctx) */
    module: string;
    /** The package whose schema changed, or null for a framework migration */
    package: string | null;
    /** A package migration: the oldest package version it upgrades */
    from?: string;
    /** A package migration: the package version it upgrades to */
    to?: string;
    decision?: string;
    /** The route aliases file that keeps the old routes working */
    aliases?: string;
  }[];
  packages: {
    [key: string]: {
      version: string;
      channel: "stable" | "experimental";
      note?: string;
    };
  };
};

/** One piece of cited evidence behind a validation record (EE-026), shared by every validation sub-score. schema/check-validation.mjs grades each item from its kind, audience, sample, specificity and age (adapted from GRADE), and grades the record from its items. A claim with no evidence grades very low. */
export type ValidationEvidence = {
  id: string;
  /** behavior: what people did (retention, payments, repeat use, money or time already spent on workarounds); commitment: what they put at stake (deposit, pre-order, letter of intent, time booked); stated: what they said when asked (interview, survey); desk-research: published data or reports; opinion: unprompted praise, advice or compliments */
  kind: "behavior" | "commitment" | "stated" | "desk-research" | "opinion";
  /** What the evidence shows, specific enough to check */
  summary: string;
  /** false when the evidence contradicts the claim */
  supports?: boolean;
  /** Where to see it: a URL with the date it was checked, or a file relative to the venture folder (interview notes, a data export), or both */
  source: {
    title?: string;
    /**
     * @format uri
     */
    url?: string;
    /**
     * @format date
     */
    checked?: string;
    path?: string;
  };
  /** Whether the people behind it are the venture's target segment for this claim (for pricing, the buyer) */
  audience: "target" | "adjacent" | "wrong" | "unknown";
  sample?: {
    n: number;
    types?: string[];
  };
  /** specific: past facts, numbers, named instances; general: hypotheticals, generalities, opinions about the future (The Mom Test) */
  specificity?: "specific" | "general";
  /**
   * @format date
   */
  collected: string;
  /** Problem records only (EE-050): the assumption the item bears on. exists: the problem is real; segment: our segment has it; hurts: it costs enough that people already spend time or money on it; why-now: something has changed. Without it the item counts toward exists. schema/assess-problem.mjs labels each assumption from its items. */
  assumption?: "exists" | "segment" | "hurts" | "why-now";
  /** first-hand: the venture saw it (its own interviews, payments, data exports); reported: someone else says so (a vendor's customer count, a report, a roundup). Defaults to first-hand for a file in the venture folder and reported for a URL. Only first-hand evidence can demonstrate an assumption (EE-050). */
  origin?: "first-hand" | "reported";
  /** Problem records only (EE-050): the id of the form the item bears on. It counts for that form and for the root. */
  form?: string;
};

/** One tester's answers at one beta checkpoint, at <venture>/validation/feedback/<id>.json. The beta gate (schema/beta-gate.mjs) unlocks the next capability only once this record exists for the previous one. routed_to is where the feedback went and routing how that was decided. */
export type ValidationFeedback = {
  id: string;
  venture?: string;
  /**
   * @format date-time
   */
  at: string;
  /** An anonymous id (NAIVE_BETA_TESTER), never a name or email: it is part of the record's file name */
  tester: string;
  /** A capability id from beta/capabilities.json */
  capability: string;
  /** The checkpoint whose form these answer */
  checkpoint: string;
  /** Question id to answer */
  answers: {
    [key: string]: string | number | boolean;
  };
  /** The route the feedback was filed under (product/bugs, validation/feedback, ...) */
  routed_to?: string | null;
  routing?: {
    model: string;
    confidence: number;
    /** True when the injected fallback decided, not Jev */
    fallback: boolean;
  };
};

/** The go-to-market sub-score (EE-026), at <venture>/purpose/validation/go-to-market.json: the path (build first, market first, cofounder first), the motion and the channels, with cited evidence that a channel reaches the segment at a known cost. The path sets the validation weights. */
export type ValidationGoToMarket = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  /** build-first: ship, then sell; market-first: market the core product before the flagship ships (waitlists, pre-orders); cofounder-first: form the team before the product */
  path: "build-first" | "market-first" | "cofounder-first";
  motion?: "product-led" | "sales-led" | "marketing-led" | "community-led" | "partner-led";
  channels: {
    id: string;
    /** e.g. search, social, outbound, referral, marketplace, partner, events */
    kind: string;
    cost_per_customer?: number;
    currency?: string;
    conversion?: number;
  }[];
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** One problem interview in the validation study, at <venture>/validation/interviews/<id>.json: who (anonymised), under what consent, what they said hurts, what they use now, the problem they chose, what the interviewer predicted with Naive and without it, and the follow-up that checks the prediction. The transcript itself stays in raw/ and is cited, never copied here. */
export type ValidationInterview = {
  /** Equal to the file name */
  id: string;
  venture?: string;
  /**
   * The day of the interview
   * @format date
   */
  at?: string;
  /** An anonymised reference (p-07), never a name or contact detail; the key to the real person stays in a _private record */
  person: string;
  /** The ideal customer profile id (foundation/icp/<id>.json) this person fits */
  icp: string;
  consent: {
    given: boolean;
    /**
     * @format date-time
     */
    at: string;
    method: "written" | "verbal-recorded" | "form" | "email";
  };
  /** The raw source the transcript lives in */
  transcript: {
    /** A raw source id or venture path (raw/sources/<id>) */
    source: string;
  };
  bottlenecks: string[];
  current_solutions?: {
    /** The bottleneck it is used for */
    for: string;
    what_it_does: string;
    what_it_doesnt?: string;
  }[];
  /** The one bottleneck the person chose to work on */
  chosen_problem?: string;
  prediction?: {
    /** What the interviewer predicts happens with Naive */
    with_naive: string;
    /** What the interviewer predicts happens without it */
    status_quo: string;
  };
  follow_up?: {
    /**
     * @format date
     */
    date: string;
    outcome_vs_prediction?: "matched" | "better" | "worse" | "mixed" | "no-outcome";
    /** Evidence record ids behind the outcome */
    evidence?: string[];
  };
};

/** The operations-readiness sub-score (EE-026), at <venture>/purpose/validation/operations-readiness.json: one entry per MAD tier (governance, delivery, software engineering, automation), each with its own evidence; the record grades as its weakest tier. */
export type ValidationOperationsReadiness = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  tiers: {
    tier: "governance" | "delivery" | "software-engineering" | "automation";
    /**
     * When the tier's records and checks first held for the phase's work
     * @format date
     */
    ready_on?: string;
    evidence: ValidationEvidence[];
  }[];
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The pricing sub-score (EE-026), at <venture>/purpose/validation/pricing.json: the price model and points, who pays, and cited evidence that the buyer pays it. */
export type ValidationPricing = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  product: string;
  model: "subscription" | "one-time" | "usage" | "freemium" | "transaction-fee" | "licence" | "donation" | "other";
  /** Who pays; may differ from the user */
  buyer: string;
  points?: {
    name: string;
    amount: number;
    /** What it costs to deliver this point, in the same currency as amount. finance/lint warns when amount is below this cost. */
    cost?: number;
    currency: string;
    period?: "once" | "day" | "week" | "month" | "year" | "use";
  }[];
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The problem sub-score (EE-026), at <venture>/purpose/validation/problem.json: the problem, who has it, how they cope today, and the cited evidence that it is real. A statement alone is the weakest form of this record; schema/check-validation.mjs grades it from its evidence. */
export type ValidationProblem = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  /** The problem in the words of the people who have it */
  statement: string;
  /** Who has it, specifically enough to find them */
  segment: string;
  /** How often it happens to them */
  frequency?: string;
  /** What it costs them now: money, time, risk */
  cost?: string;
  /** How they cope today; money or time already spent on a workaround is strong evidence */
  workarounds?: string[];
  /** What has changed that makes the problem solvable or urgent now (EE-050) */
  why_now?: string;
  /** The forms the problem takes (EE-050): one root problem in statement, and each form a narrower problem with its own segment and evidence, assessed on its own so it can be validated or dropped without touching the root */
  forms?: {
    id: string;
    statement: string;
    /** Only when narrower than the root's */
    segment?: string;
    status?: "open" | "dropped";
  }[];
  evidence: ValidationEvidence[];
  /** The Jev probability that the problem is real and worth solving for this segment; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The product-market fit sub-score (EE-026), at <venture>/purpose/validation/product-market-fit.json: whether a segment keeps using the product. Retention cohorts and the Sean Ellis survey are recorded as data; schema/check-validation.mjs reads them (does retention level off; what share would be very disappointed). */
export type ValidationProductMarketFit = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  product: string;
  segment: string;
  retention?: {
    period: "day" | "week" | "month";
    cohorts: {
      /**
       * @format date
       */
      start: string;
      size: number;
      /** Active users at the end of each period after the cohort started */
      active: number[];
    }[];
  };
  /** Sean Ellis survey: how would you feel if you could no longer use the product? Asked of active users */
  ellis?: {
    asked: number;
    very_disappointed: number;
    /**
     * @format date
     */
    collected?: string;
  };
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The solution sub-score (EE-026), at <venture>/purpose/validation/solution.json: how the venture solves the problem, what people use instead, and cited evidence that people in the segment choose it over their current way. */
export type ValidationSolution = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  /** How it solves the problem, in one or two sentences */
  statement: string;
  /** Product id, if one product carries the solution */
  product?: string;
  /** What people use instead today, including doing nothing */
  alternatives: string[];
  /** Why someone would switch */
  difference?: string;
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The team sub-score (EE-026), at <venture>/purpose/validation/team.json: the skills the coming phases need, the skills held and by whom, and the gaps, including whether a cofounder is sought for them. schema/check-validation.mjs lists the gaps. */
export type ValidationTeam = {
  venture: string;
  /**
   * @format date
   */
  updated?: string;
  needed: {
    skill: string;
    by_phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
    why?: string;
  }[];
  held: {
    skill: string;
    /** A role id, or 'agent:<role>' when an agent holds it */
    by: string;
  }[];
  cofounder_sought?: boolean;
  cofounder_skills?: string[];
  evidence: ValidationEvidence[];
  /** The Jev probability for this sub-score; the evidence grade weighs it in the validation score */
  probability?: {
    p: number;
    by: "jev" | "owner";
    /**
     * @format date
     */
    scored: string;
    note?: string;
  };
};

/** The roles a person can hold in a venture (governance/venture-template/roles/venture-roles.json), as distinct from the agent roles beside it. create-venture asks for one; people/people.json records who holds which. */
export type VentureRole = {
  version: string;
  note?: string;
  roles: {
    id: string;
    name: string;
    kind: "builder" | "investor" | "operator" | "advisor" | "governor";
    description: string;
    /** Whether the holder is a founder of this venture, with a file in people/founders/ and a place in the founder agreement */
    founder: boolean;
    /** Whether a person alone in this role owns every function the venture imports */
    owns_when_solo: boolean;
  }[];
};

/** The kinds of venture create-venture scaffolds (schema/venture-types.json). A venture's type decides its starting packages, its first decisions, the functions it imports and the roles a person can hold in it. venture.json names its type. */
export type VentureTypes = {
  version: string;
  note?: string;
  types: {
    id: string;
    label: string;
    description: string;
    /** Words a founder might use for it; the classifier reads them */
    examples: string[];
    /** Role ids from governance/venture-template/roles/venture-roles.json a person can hold in this type */
    roles: string[];
    default_role: string;
    /** Functions the type imports from the start (operations/departments.json); a solo founder owns them all */
    departments: ("strategy" | "products" | "marketing-and-sales" | "supply-chain" | "service-delivery" | "customer-service" | "human-capital" | "it" | "finance" | "assets" | "risk-and-compliance" | "external-relationships" | "capabilities")[];
    /** Package directories created at the venture root */
    packages: string[];
    /** The first questions the venture answers, written as open decisions by the scaffold */
    decisions: "product-foundation" | "fund-foundation" | "none";
    funding?: "bootstrapped" | "grant" | "angel" | "venture-capital" | "debt" | "mixed";
    /** Layers on from the start, when the phase's defaults would leave a layer the type needs off */
    layers?: ("purpose" | "knowledge" | "operations" | "evidence" | "governance" | "interface")[];
  }[];
};

/** One venture: anything a builder undertakes, from a hobby to a company (EE-011). Each venture keeps a venture.json at its root, beside its venture profile. Its products are cards in products/, the parties it keeps records for are accounts in accounts/ (optional, EE-021), and ventures can hold ventures. Cross-venture rules are checked by schema/check-ventures.mjs. Nouns follow docs/ontology.md (EE-014). */
export type Venture = {
  id: string;
  name: string;
  /** venture: building a venture, whose root and strategic foundation fail closed. product: a product without a venture, which fails open (EE-054). */
  kind?: "venture" | "product";
  /** The venture type, an id from schema/venture-types.json: what kind of venture this is (a software startup, a VC fund), which decides its starting packages, first decisions, functions and roles (EE-082) */
  type?: string;
  /** Where the venture's files sit (EE-086). structured: venture.json, README.md and AGENTS.md at the top, the knowledge base in knowledge/, sources.json, naive.config.json, the provenance log and releases in meta/, and code in an optional repo/. flat: every venture made before EE-086, with packages at the top. */
  layout?: "flat" | "structured";
  /** The venture's functions and their one accountable owner each (EE-071), keyed by function id from operations/departments.json. A solo founder owns them all, which is what the manifest assumes when this is left out. */
  functions?: {
    [key: string]: {
      /** A role or a person's name; no personal details */
      owner: string;
    };
  };
  /** The id of the venture that holds this one; null at the top of a workspace. */
  parent: string | null;
  /** How far the venture has come (EE-012). discovery: does a real problem exist, and who has it. validation: will people adopt this solution and keep using it. beachhead: can it win one segment repeatably at a profitable cost. scale: how fast can it take the mass market. platform: what will others build on. Gates and references: purpose/frameworks/product-anatomy/phases.json. */
  phase: "discovery" | "validation" | "beachhead" | "scale" | "platform";
  /** The venture's IANA time zone, when it differs from its workspace's (schema/clock.mjs); its dates, activity days and derived calendar events are read in it. Unset: the workspace's, else the system's */
  timeZone?: string;
  /** The lifecycle playbook the venture follows (purpose/frameworks/product-anatomy/playbooks/<id>.json): the order of its decisions and the evidence that clears each phase gate. Absent means product-first, Naive's default. */
  lifecycle_playbook?: string;
  /** Why the venture exists and how far through the phases it means to go. hobby follows the IRS sense: not engaged in for profit. */
  ambition?: "hobby" | "survival" | "lifestyle" | "managed-growth" | "aggressive-growth";
  /** Whether and how the venture is formalized. */
  form?: {
    legal_form?: "none" | "sole-prop" | "partnership" | "llc" | "s-corp" | "c-corp" | "benefit-corp" | "nonprofit";
    funding?: "bootstrapped" | "grant" | "angel" | "venture-capital" | "debt" | "mixed";
  };
  /** What the venture produces, by its current flagship. Re-checked at each phase gate. */
  industry?: {
    /** NAICS (North American Industry Classification System), production-oriented */
    system: "naics";
    code: string;
    label?: string;
  };
  /** The core product (Product Anatomy): what anyone can claim from this venture. Required once the venture leaves discovery. The mission (promise) can be decided and land on its own; promised_to, must_not and competence follow as they are decided, and the foundation report names any still missing. */
  core?: {
    promise: string;
    promised_to?: string;
    /** What it must never deliver under its name */
    must_not?: string;
    /** The core competence that makes the promise deliverable (Prahalad and Hamel) */
    competence?: string;
  };
  /** The departments this venture imports, by id from operations/departments.json (EE-047). Only these get folders; the rest are not in the venture at all until need-now suggests them and the builder adds them (EE-048). */
  departments?: string[];
  /** The Naive packages this venture uses, by name from packages/ (EE-071), the way package.json lists dependencies (Next.js translation P-3). Left out, the manifest derives them: the core packages that fit the phase now plus any package holding records. Checked by schema/structure.mjs. */
  packages?: string[];
  /** The Mentura kits this venture uses (EE-071). Each names the one package it extends, which the venture must use; the kit itself lives on the platform. */
  kits?: {
    id: string;
    extends: string;
  }[];
  /** The venture's verbal brand elements, owned by the brand pillar. Visual identity (tokens, logos) is a separate record. */
  brand?: {
    /** The brand's enduring short line, kept across campaigns (Burger King's 'Have it your way'). A campaign's slogan is not this; it belongs to the campaign. */
    tagline?: string;
  };
  owner: "self" | "shared" | "other";
  /** The others who work in the venture, by role, people and agents alike: a string role (co-founder, partner, investor) or an object naming the kind. No personal details. Any member switches on governance, since agents need decision rights too. */
  members?: (string | {
    /** A role id from the roles register (builder, architect) or a plain role */
    role: string;
    kind: "person" | "agent";
    /** For agents: the interfaces or runtimes it runs in (integration ids) */
    tools?: string[];
  })[];
  governed_by?: string;
  status: "active" | "paused" | "closed" | "archived";
  /**
   * @format date
   */
  opened?: string;
  /**
   * @format date
   */
  closed?: string;
  /** Path to the venture profile (Markdown): narrative, pillars and changelog. */
  profile?: string;
  /** Every venture has the same six layers (execution folded into operations, EE-038), at the depth it needs. A layer not used yet is false. */
  layers: {
    purpose: VentureLayer;
    knowledge: VentureLayer;
    operations: VentureLayer;
    evidence: VentureLayer;
    governance?: VentureLayer;
    interface?: VentureLayer;
  };
  /** What crosses from this venture into another, one way. */
  links?: {
    to: string;
    access: "reads" | "shares-with";
    carries: string[];
    border?: "closed" | "filtered" | "open";
  }[];
  tags?: string[];
  /** The venture's repositories (repo is short for repository): version-controlled stores, normally Git, holding code and the documents that ship with it (docs-as-code). The venture folder itself lives in the vault. A venture that builds software needs at least one; ventures in other industries may need none (EE-020) */
  repos?: {
    id: string;
    /**
     * @format uri
     */
    url?: string;
    /** Path relative to the workspace's code folder */
    location?: string;
    /** Product ids whose code it holds */
    products?: string[];
  }[];
  /** How much laws, regulators or formal standards constrain what the venture may do (EE-040; MAD's governance tier reads it as regulatory_exposure). The obligations themselves are founder decisions made with counsel. */
  regulation?: {
    /** light: ordinary terms of service and licences. some: obligations such as personal data, accessibility rules or industry codes. heavy: health, finance, safety-critical or government work, where an auditor or regulator must be satisfied. */
    exposure?: "light" | "some" | "heavy";
    /** The laws, regulators or standards that apply, such as GDPR, HIPAA or SOC 2 */
    regimes?: string[];
  };
};

export type VentureLayer = false | {
  /** Folder path, relative to the folder that holds venture.json */
  location: string;
  tools?: string[];
};

/** A venture's where-used list (<venture>/knowledge/where-used.json, EE-042): for each fact kept once in its system of record (a parent, such as a product's price), every place that repeats it (its children: a pricing page, a newsletter, a payment provider, a constant in code). Update the parent once and the children show what must follow. The framework checks live children offline and reports drift (schema/check-where-used.mjs); delivering the change into a vendor's system is the platform's (coexistence or centralized style). Written for a fast model to read: every field present. */
export type WhereUsed = {
  facts: {
    id: string;
    /** Where the fact is mastered: a record route and a JSON pointer into it */
    parent: {
      /** A record route, such as purpose/product/shop-app */
      route: string;
      /** A JSON pointer to the value, such as /price */
      pointer: string;
    };
    children: {
      /** A source id from knowledge/sources.json, or venture for the venture's own folder */
      source: string;
      /** The file inside that source */
      path: string;
      match: {
        kind: "text";
        /** How the value appears in the text, {value} standing for it, such as $ {value}/month */
        template: string;
      } | {
        kind: "json";
        pointer: string;
      };
      /** live: must always show the parent's value. frozen: history that keeps the value it had (a newsletter already sent, a past invoice); never checked or changed */
      status: "live" | "frozen";
      /** Who carries a change to this child: an agent through a handoff, a person, or the platform's sync */
      deliver: "agent" | "person" | "platform";
      note?: string;
    }[];
    note?: string;
  }[];
  note?: string;
};

/** A builder's workspace: one instance of the system. A naive-workspace.json (earlier workspace.json) at its top says which schema version it follows, where its vault is and where its repositories are (EE-002, EE-011, EE-020). A workspace always has a vault; it has a code folder of repositories once any venture builds software. One schema covers both file names; naive-workspace.json is the name create-venture writes. A teammate's own workspace can list ventures they work for or with; each venture keeps its own settings, and the workspace's settings govern what crosses between them. */
export type Workspace = {
  schema: "everything-ecosystem";
  /** The version in schema/VERSION that this workspace follows */
  schema_version: string;
  /** The workspace's name, shown to the founder. A new workspace is named "Naive workspace"; the founder renames it with naive workspace rename */
  name?: string;
  /** Folders to search for venture.json files, relative to the workspace. Grouping folders inside them are for people to browse and carry no meaning; each venture.json is the truth. */
  ventures: string[];
  /** The folder holding the ventures' repositories (repository, short repo: a version-controlled store, normally Git, for code and the documents that ship with it). Needed once any venture builds software */
  code?: string;
  /** The vault: the folder of documents (Markdown and JSON records) that holds the venture folders, their records and their decisions. Relative to the workspace; defaults to the workspace itself. Any notes app can open it; Obsidian calls such a folder a vault */
  vault?: string;
  /** The workspace's own configuration, set by the founder. Offline (a local folder) these are the whole of it. */
  settings?: {
    /** Whether a session in one venture may read another venture in this workspace. Only published artifacts ever cross; records and _private/ never do. On unless the founder turns it off */
    cross_venture_reads?: boolean;
    /** How sure naive capture must be before it files a chunk in a venture's inbox by itself; below it the chunk waits in the workspace inbox for the founder */
    route_threshold?: number;
  };
  /** The founder record, relative to the workspace (normally founder/founder.json) */
  founder?: string;
  /** The workspace's IANA time zone (for example America/New_York): the clock's zone (schema/clock.mjs). Set when the workspace is initiated, from the system's zone unless given; a venture.json timeZone overrides it for that venture */
  timeZone?: string;
  /** The calendar folder, relative to the workspace (calendar/): calendars/<id>.json and events/<uid>.json (schema/calendar.mjs). Created with the workspace */
  calendar?: string;
};
